  "No punches recorded yet.": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ପଞ୍ଚ୍ ରେକର୍ଡ ହୋଇନାହିଁ।",
  "Submit a correction for a missed or incorrect punch. Your manager will review and approve within the regularization cutoff window (7 days after month end).": "ଛୁଟିଯାଇଥିବା କିମ୍ବା ଭୁଲ ପଞ୍ଚ୍ ପାଇଁ ସଂଶୋଧନ ଦାଖଲ କରନ୍ତୁ। ଆପଣଙ୍କ ମ୍ୟାନେଜର ନିୟମିତକରଣର ଶେଷ ସମୟ (ମାସ ଶେଷର 7 ଦିନ ପରେ) ମଧ୍ୟରେ ସମୀକ୍ଷା କରି ଅନୁମୋଦନ କରିବେ।",
