  "Adds a punch-out at this time. Your punch-in for the day stays as it is.": "ଏହି ସମୟରେ ପଞ୍ଚ୍-ଆଉଟ୍ ଯୋଗ କରେ। ସେହି ଦିନର ଆପଣଙ୍କ ପଞ୍ଚ୍-ଇନ୍ ଯେମିତି ଅଛି ସେମିତି ରହିବ।",
