  // Home banner, tax notices and late-login text
  "You are viewing this workspace read-only. Nothing you do here is saved.": "ଆପଣ ଏହି କାର୍ଯ୍ୟକ୍ଷେତ୍ର କେବଳ ଦେଖିବା ପାଇଁ ଖୋଲିଛନ୍ତି। ଏଠାରେ ଆପଣ ଯାହା କରିବେ ତାହା ସଞ୍ଚିତ ହେବ ନାହିଁ।",
  "Requests are recorded against your employee record and routed to the approver shown on each one.": "ଅନୁରୋଧ ଆପଣଙ୍କ କର୍ମଚାରୀ ରେକର୍ଡରେ ଦର୍ଜ ହୁଏ ଏବଂ ପ୍ରତ୍ୟେକ ଉପରେ ଦେଖାଯାଇଥିବା ଅନୁମୋଦନକାରୀଙ୍କ ପାଖକୁ ପଠାଯାଏ।",
  "Tax declaration approved": "କର ଘୋଷଣା ଅନୁମୋଦିତ",
  "Tax declaration window is open": "କର ଘୋଷଣାର ସମୟ ଖୋଲା ଅଛି",
  "Your {year} regime and declarations were approved. Further changes follow payroll approval.": "ଆପଣଙ୍କ {year} ର ବ୍ୟବସ୍ଥା ଓ ଘୋଷଣା ଅନୁମୋଦିତ ହୋଇଛି। ଆଗାମୀ ପରିବର୍ତ୍ତନ ପେରୋଲ୍ ଅନୁମୋଦନ ଅନୁସାରେ ହେବ।",
