  "Cards": "କାର୍ଡ",
  "Changes employees ask HR to make to their profile. Everyone who answers HR Help tickets, and any full-access user, sees all of them.": "କର୍ମଚାରୀମାନେ ନିଜ ପ୍ରୋଫାଇଲ୍ ରେ HR ଙ୍କୁ କରିବାକୁ କହୁଥିବା ପରିବର୍ତ୍ତନ। HR ସହାୟତା ଟିକେଟ୍ ର ଉତ୍ତର ଦେଉଥିବା ସମସ୍ତେ ଏବଂ ଯେକୌଣସି ପୂର୍ଣ୍ଣ-ଅଧିକାର ଉପଯୋଗକର୍ତ୍ତା ସେସବୁ ଦେଖନ୍ତି।",
  "Counts show only what the server lets you see. Onboarding approvals are in Review & Onboarding, and bank-change requests are in the employee record; they are not part of this list.": "ଗଣନା କେବଳ ସର୍ଭର ଆପଣଙ୍କୁ ଯାହା ଦେଖିବାକୁ ଦିଏ ତାହା ଦେଖାଏ। ଅନବୋର୍ଡିଂ ଅନୁମୋଦନ \"ସମୀକ୍ଷା ଓ ଅନବୋର୍ଡିଂ\" ରେ ଅଛି, ଏବଂ ବ୍ୟାଙ୍କ ପରିବର୍ତ୍ତନ ଅନୁରୋଧ କର୍ମଚାରୀ ରେକର୍ଡରେ ଅଛି; ସେଗୁଡ଼ିକ ଏହି ତାଲିକାର ଅଂଶ ନୁହେଁ।",
  "Cycle sign-off for your team or payroll scope. Open the tab to see what is due.": "ଆପଣଙ୍କ ଦଳ କିମ୍ବା ପେରୋଲ୍ ପରିସର ପାଇଁ ଚକ୍ର ସ୍ୱାକ୍ଷର। କଣ ବାକି ଅଛି ଦେଖିବାକୁ ଟାବ୍ ଖୋଲନ୍ତୁ।",
  "Employees assigned to you; with no assigned HR, employees on your branch. A full-access user sees all.": "ଆପଣଙ୍କୁ ଦିଆଯାଇଥିବା କର୍ମଚାରୀ; କୌଣସି HR ଦିଆଯାଇନଥିଲେ, ଆପଣଙ୍କ ଶାଖାର କର୍ମଚାରୀ। ପୂର୍ଣ୍ଣ-ଅଧିକାର ଉପଯୋଗକର୍ତ୍ତା ସମସ୍ତଙ୍କୁ ଦେଖନ୍ତି।",
  "Everything else": "ଅନ୍ୟ ସବୁକିଛି",
