  "Personnel actions & approval inbox": "କର୍ମଚାରୀ କାର୍ଯ୍ୟାନୁଷ୍ଠାନ ଓ ଅନୁମୋଦନ ଇନ୍‌ବକ୍ସ",
  "Promotions, transfers, pay changes and confirmations. Nothing changes until the last approver approves.": "ପଦୋନ୍ନତି, ବଦଳି, ଦରମା ପରିବର୍ତ୍ତନ ଓ ସ୍ଥାୟୀକରଣ। ଶେଷ ଅନୁମୋଦନକାରୀ ଅନୁମୋଦନ ନକରିବା ପର୍ଯ୍ୟନ୍ତ କିଛି ବଦଳେ ନାହିଁ।",
