  "WFH, field work, biometric failure…": "ଘରୁ କାମ, ଫିଲ୍ଡ କାମ, ବାୟୋମେଟ୍ରିକ୍ ବିଫଳତା…",
  ". Employees cannot register a face ID or be asked to verify — their Profile page shows “Contact admin to use this feature”, and no punch requires a face match.": "। କର୍ମଚାରୀମାନେ Face ID ପଞ୍ଜୀକରଣ କରିପାରିବେ ନାହିଁ କିମ୍ବା ଯାଞ୍ଚ କରିବାକୁ କୁହାଯିବ ନାହିଁ — ସେମାନଙ୍କ ପ୍ରୋଫାଇଲ୍ ପୃଷ୍ଠାରେ “ଏହି ସୁବିଧା ବ୍ୟବହାର କରିବାକୁ ଆଡମିନ୍ ଙ୍କୁ ଯୋଗାଯୋଗ କରନ୍ତୁ” ଦେଖାଯାଏ, ଏବଂ କୌଣସି ପଞ୍ଚ୍ ପାଇଁ ଫେସ୍ ମେଳ ଆବଶ୍ୟକ ନୁହେଁ।",
