  "A fallback punch must still be from inside the office geofence. It is flagged on the punch and recorded in the Audit Log.": "ବିକଳ୍ପ ପଞ୍ଚ୍ ମଧ୍ୟ ଅଫିସ୍ ଜିଓଫେନ୍ସ ଭିତରୁ ହେବା ଆବଶ୍ୟକ। ଏହା ପଞ୍ଚ୍ ଉପରେ ଚିହ୍ନିତ ହୁଏ ଏବଂ ଅଡିଟ୍ ଲଗ୍ ରେ ଦର୍ଜ ହୁଏ।",
