  "Every message (the clock-in error, the Profile page, the Face ID Registrations screen, the hire screen and the welcome email) follows this choice.": "ପ୍ରତ୍ୟେକ ବାର୍ତ୍ତା (କ୍ଲକ୍-ଇନ୍ ତ୍ରୁଟି, ପ୍ରୋଫାଇଲ୍ ପୃଷ୍ଠା, Face ID ପଞ୍ଜୀକରଣ ସ୍କ୍ରିନ୍, ନିଯୁକ୍ତି ସ୍କ୍ରିନ୍ ଓ ସ୍ୱାଗତ ଇମେଲ୍) ଏହି ପସନ୍ଦ ଅନୁସରଣ କରେ।",
  "Face ID registration is": "Face ID ପଞ୍ଜୀକରଣ",
  "Face ID Verification": "Face ID ଯାଞ୍ଚ",
  "Face ID verification is": "Face ID ଯାଞ୍ଚ",
  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "ପ୍ରତ୍ୟେକ କର୍ମଚାରୀଙ୍କ ପାଇଁ। ପ୍ରତ୍ୟେକ ୱେବ୍ ପଞ୍ଚ୍ ପାଇଁ ଏକ ଅନୁମୋଦିତ Face ID ସହ ସିଧା ଫେସ୍ ମେଳ ଆବଶ୍ୟକ; ଯେପର୍ଯ୍ୟନ୍ତ ତାହା ନାହିଁ, ଆପଣ ତଳେ ଥିବା ବିକଳ୍ପକୁ ଅନୁମତି ନଦେଲେ ୱେବ୍ କ୍ଲକ୍-ଇନ୍/ଆଉଟ୍ ଅବରୋଧିତ ରହେ।",
  "Forgive late arrival when full hours are completed": "ପୂରା ଘଣ୍ଟା ସମ୍ପୂର୍ଣ୍ଣ ହେଲେ ବିଳମ୍ବରେ ଆସିବା କ୍ଷମା କରନ୍ତୁ",
  "Grace Period (min)": "ଗ୍ରେସ୍ ଅବଧି (ମିନିଟ୍)",
  "Half-Day Limit (hours or fewer)": "ଅଧା ଦିନ ସୀମା (ଘଣ୍ଟା କିମ୍ବା କମ୍)",
  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "କର୍ମଚାରୀ କେତେ ଦିନ ପଛକୁ ଘରୁ କାମ ଅନୁରୋଧ କରିପାରିବେ। ଅନୁମତି ନାହିଁ (ସୁପାରିଶିତ): କେବଳ ଆଜି କିମ୍ବା ପରବର୍ତ୍ତୀ ତାରିଖ, କାରଣ ଅତୀତ ଦିନ ପାଇଁ ଅନୁମୋଦିତ ଅନୁରୋଧ ପରେ ସେହି ଦିନର ସ୍ଥିତି ବଦଳାଇ ଦିଏ ଏବଂ ଘର-ସ୍ଥାନ ଯାଞ୍ଚ ପୂରଣ ହୋଇପାରେ ନାହିଁ।",
  "HR only": "କେବଳ HR",
  "Late Mark & LOP Rule": "ବିଳମ୍ବ ଚିହ୍ନ ଓ LOP ନିୟମ",
