  "Notify": "ଜଣାନ୍ତୁ",
  "Notify HR and the manager when an employee is absent for N+ consecutive working days without approved leave.": "ଅନୁମୋଦିତ ଛୁଟି ବିନା କର୍ମଚାରୀ N+ ଲଗାତାର କାର୍ଯ୍ୟ ଦିବସ ଅନୁପସ୍ଥିତ ରହିଲେ HR ଓ ମ୍ୟାନେଜରଙ୍କୁ ଜଣାନ୍ତୁ।",
  "off": "ବନ୍ଦ",
  "Off (recommended): a finished day of the half-day limit or fewer is a Half Day; a day above it but short of the full-day minimum stays Present and is shown as “hours not completed” with the minutes short. On: every day below the full-day minimum is a Half Day.": "ବନ୍ଦ (ସୁପାରିଶିତ): ଅଧା ଦିନ ସୀମା କିମ୍ବା ତା'ଠାରୁ କମ୍ ଘଣ୍ଟାର ସମାପ୍ତ ଦିନ ଅଧା ଦିନ ଗଣାଯାଏ; ସୀମାଠାରୁ ଅଧିକ କିନ୍ତୁ ପୂର୍ଣ୍ଣ ଦିନର ସର୍ବନିମ୍ନଠାରୁ କମ୍ ଥିବା ଦିନ ଉପସ୍ଥିତ ରହେ ଏବଂ କମ୍ ମିନିଟ୍ ସହ “ଘଣ୍ଟା ପୂରଣ ହୋଇନାହିଁ” ଭାବେ ଦେଖାଯାଏ। ଚାଲୁ: ପୂର୍ଣ୍ଣ ଦିନର ସର୍ବନିମ୍ନଠାରୁ କମ୍ ଥିବା ପ୍ରତ୍ୟେକ ଦିନ ଅଧା ଦିନ ଗଣାଯାଏ।",
