  "Someone who arrives after the grace period but works the full-day hours is marked Present and gets no late mark. The late arrival stays as a note.": "ଗ୍ରେସ୍ ଅବଧି ପରେ ଆସି ମଧ୍ୟ ପୂର୍ଣ୍ଣ ଦିନର ଘଣ୍ଟା କାମ କରୁଥିବା ବ୍ୟକ୍ତି ଉପସ୍ଥିତ ଚିହ୍ନିତ ହୁଅନ୍ତି ଏବଂ ବିଳମ୍ବ ଚିହ୍ନ ପାଆନ୍ତି ନାହିଁ। ବିଳମ୍ବରେ ଆସିବା ଏକ ଟିପ୍ପଣୀ ଭାବେ ରହେ।",
  "Treat every day below the full day as a Half Day": "ପୂର୍ଣ୍ଣ ଦିନଠାରୁ କମ୍ ପ୍ରତ୍ୟେକ ଦିନକୁ ଅଧା ଦିନ ଗଣନ୍ତୁ",
