  "Worked hours after the break is deducted. Shift length minus the break makes overtime start exactly at shift end.": "ବ୍ରେକ୍ କଟାଯିବା ପରେ କାମ କରିଥିବା ଘଣ୍ଟା। ସିଫ୍ଟ ଲମ୍ବ ମାଇନସ୍ ବ୍ରେକ୍ ଫଳରେ ଓଭରଟାଇମ୍ ଠିକ୍ ସିଫ୍ଟ ଶେଷରେ ଆରମ୍ଭ ହୁଏ।",
