  "Requests from employees to fix a missed or wrong punch. Approve or reject each one.": "ଛୁଟିଯାଇଥିବା କିମ୍ବା ଭୁଲ ପଞ୍ଚ୍ ଠିକ୍ କରିବାକୁ କର୍ମଚାରୀଙ୍କ ଅନୁରୋଧ। ପ୍ରତ୍ୟେକକୁ ଅନୁମୋଦନ କିମ୍ବା ପ୍ରତ୍ୟାଖ୍ୟାନ କରନ୍ତୁ।",
