  "No clock-in or clock-out was captured. If they did work, use Edit to record it.": "କୌଣସି କ୍ଲକ୍-ଇନ୍ କିମ୍ବା କ୍ଲକ୍-ଆଉଟ୍ ଧରାପଡ଼ିଲା ନାହିଁ। ଯଦି ସେମାନେ କାମ କରିଥିଲେ, ତାହା ରେକର୍ଡ କରିବାକୁ ସମ୍ପାଦନ ବ୍ୟବହାର କରନ୍ତୁ।",
