  "employees": "କର୍ମଚାରୀ",
  "every active employee (no branch/department filter)": "ପ୍ରତ୍ୟେକ ସକ୍ରିୟ କର୍ମଚାରୀ (କୌଣସି ଶାଖା/ବିଭାଗ ଫିଲ୍ଟର ନାହିଁ)",
  "Failed to assign pattern.": "ପ୍ୟାଟର୍ନ ଦେବା ବିଫଳ ହେଲା।",
  "Past attendance is never affected — this pattern applies from the effective date forward only.": "ଅତୀତ ଉପସ୍ଥିତି କେବେ ପ୍ରଭାବିତ ହୁଏ ନାହିଁ — ଏହି ପ୍ୟାଟର୍ନ କେବଳ କାର୍ଯ୍ୟକାରୀ ତାରିଖରୁ ଆଗକୁ ଲାଗୁ ହୁଏ।",
  "Select pattern…": "ପ୍ୟାଟର୍ନ ବାଛନ୍ତୁ…",
  "the selected pattern": "ବଛାଯାଇଥିବା ପ୍ୟାଟର୍ନ",
  "This assigns \"{pattern}\" effective {date} to every active employee matching: {scope}. The exact number of employees affected is resolved on the server and isn't known until this runs.": "ଏହା \"{pattern}\" କୁ {date} ରୁ କାର୍ଯ୍ୟକାରୀ ଭାବେ ମେଳ ଖାଉଥିବା ପ୍ରତ୍ୟେକ ସକ୍ରିୟ କର୍ମଚାରୀଙ୍କୁ ଦିଏ: {scope}। ପ୍ରଭାବିତ କର୍ମଚାରୀଙ୍କ ସଠିକ୍ ସଂଖ୍ୟା ସର୍ଭରରେ ସ୍ଥିର ହୁଏ ଏବଂ ଏହା ଚଲିବା ପର୍ଯ୍ୟନ୍ତ ଜଣାନଥାଏ।",
  "Try clearing a filter above.": "ଉପରେ ଏକ ଫିଲ୍ଟର ସଫା କରି ଦେଖନ୍ତୁ।",
  "Weekly Off Pattern": "ସାପ୍ତାହିକ ଛୁଟି ପ୍ୟାଟର୍ନ",
  "Weekly off pattern assigned to {count} employee(s).": "{count} କର୍ମଚାରୀଙ୍କୁ ସାପ୍ତାହିକ ଛୁଟି ପ୍ୟାଟର୍ନ ଦିଆଗଲା।",
  "Weekly off pattern assigned to {name}.": "{name} ଙ୍କୁ ସାପ୍ତାହିକ ଛୁଟି ପ୍ୟାଟର୍ନ ଦିଆଗଲା।",
  "Which weekly off pattern each employee follows. A new pattern applies from its effective date forward.": "ପ୍ରତ୍ୟେକ କର୍ମଚାରୀ କେଉଁ ସାପ୍ତାହିକ ଛୁଟି ପ୍ୟାଟର୍ନ ଅନୁସରଣ କରନ୍ତି। ନୂଆ ପ୍ୟାଟର୍ନ ଏହାର କାର୍ଯ୍ୟକାରୀ ତାରିଖରୁ ଆଗକୁ ଲାଗୁ ହୁଏ।",
  "\"{name}\" will be deactivated. Employees currently assigned this pattern keep it until reassigned — history is preserved.": "\"{name}\" ନିଷ୍କ୍ରିୟ ହେବ। ବର୍ତ୍ତମାନ ଏହି ପ୍ୟାଟର୍ନ ଥିବା କର୍ମଚାରୀ ପୁନଃ ନିର୍ଦ୍ଧାରଣ ନହେବା ପର୍ଯ୍ୟନ୍ତ ଏହା ରଖିବେ — ଇତିହାସ ସୁରକ୍ଷିତ ରହେ।",
