  "Assign another pattern as default before removing this one.": "ଏହାକୁ ହଟାଇବା ପୂର୍ବରୁ ଅନ୍ୟ ଏକ ପ୍ୟାଟର୍ନକୁ ଡିଫଲ୍ଟ ଭାବେ ଦିଅନ୍ତୁ।",
  "Configure reusable weekly-off schedules and assign them to employees from Attendance & Time → Weekly Off Assignment.": "ପୁନଃବ୍ୟବହାରଯୋଗ୍ୟ ସାପ୍ତାହିକ ଛୁଟି କାର୍ଯ୍ୟସୂଚୀ ସେଟ୍ କରନ୍ତୁ ଏବଂ ଉପସ୍ଥିତି ଓ ସମୟ → ସାପ୍ତାହିକ ଛୁଟି ନିର୍ଦ୍ଧାରଣରୁ କର୍ମଚାରୀଙ୍କୁ ଦିଅନ୍ତୁ।",
