  ". This will move them to this Company Code as its Company Code Admin.": "। ଏହା ଦ୍ୱାରା ସେମାନେ ଏହି କମ୍ପାନୀ କୋଡ୍ କୁ ଏହାର କମ୍ପାନୀ କୋଡ୍ ଆଡମିନ୍ ଭାବେ ଯିବେ।",
  "Another branch is already marked as the headquarter. Setting this branch as HQ will remove the HQ status from the existing one. Do you want to continue?": "ଅନ୍ୟ ଏକ ଶାଖା ଆଗରୁ ମୁଖ୍ୟାଳୟ ଭାବେ ଚିହ୍ନିତ ଅଛି। ଏହି ଶାଖାକୁ HQ କଲେ ବର୍ତ୍ତମାନର ଶାଖାରୁ HQ ସ୍ଥିତି ହଟିଯିବ। ଆପଣ ଜାରି ରଖିବେ କି?",
  "Are you sure you want to delete": "ଆପଣ ନିଶ୍ଚିତ ଭାବେ ଡିଲିଟ୍ କରିବାକୁ ଚାହୁଁଛନ୍ତି କି",
