  "Move {name}?": "{name} କୁ ସ୍ଥାନାନ୍ତର କରିବେ?",
  "no Company Code": "କୌଣସି କମ୍ପାନୀ କୋଡ୍ ନାହିଁ",
  "They currently manage {count} employee — that reporting line won't be reassigned automatically.": "ସେମାନେ ବର୍ତ୍ତମାନ {count} କର୍ମଚାରୀଙ୍କୁ ପରିଚାଳନା କରୁଛନ୍ତି — ସେହି ରିପୋର୍ଟିଂ ଧାରା ସ୍ୱୟଂଚାଳିତ ଭାବେ ପୁନଃ ନିର୍ଦ୍ଧାରିତ ହେବ ନାହିଁ।",
  "They currently manage {count} employees — that reporting line won't be reassigned automatically.": "ସେମାନେ ବର୍ତ୍ତମାନ {count} କର୍ମଚାରୀଙ୍କୁ ପରିଚାଳନା କରୁଛନ୍ତି — ସେହି ରିପୋର୍ଟିଂ ଧାରା ସ୍ୱୟଂଚାଳିତ ଭାବେ ପୁନଃ ନିର୍ଦ୍ଧାରିତ ହେବ ନାହିଁ।",
  "They're the assigned HR for {count} employee — that assignment won't be reassigned automatically.": "ସେମାନେ {count} କର୍ମଚାରୀଙ୍କ ପାଇଁ ଦିଆଯାଇଥିବା HR — ସେହି ଦାୟିତ୍ୱ ସ୍ୱୟଂଚାଳିତ ଭାବେ ପୁନଃ ନିର୍ଦ୍ଧାରିତ ହେବ ନାହିଁ।",
  "They're the assigned HR for {count} employees — that assignment won't be reassigned automatically.": "ସେମାନେ {count} କର୍ମଚାରୀଙ୍କ ପାଇଁ ଦିଆଯାଇଥିବା HR — ସେହି ଦାୟିତ୍ୱ ସ୍ୱୟଂଚାଳିତ ଭାବେ ପୁନଃ ନିର୍ଦ୍ଧାରିତ ହେବ ନାହିଁ।",
