  "Tip: in Google Maps, right-click the office and copy the numbers, or use “Use my current location” below.": "ଟିପ୍: Google Maps ରେ କାର୍ଯ୍ୟାଳୟ ଉପରେ ରାଇଟ୍-କ୍ଲିକ୍ କରି ସଂଖ୍ୟାଗୁଡ଼ିକ କପି କରନ୍ତୁ, କିମ୍ବା ତଳେ ଥିବା “ମୋ ବର୍ତ୍ତମାନ ସ୍ଥାନ ବ୍ୟବହାର କରନ୍ତୁ” ବ୍ୟବହାର କରନ୍ତୁ।",
  "Checking…": "ଯାଞ୍ଚ ହେଉଛି…",
  "Could not read this device's location. Allow location access and try again.": "ଏହି ଡିଭାଇସ୍ ର ସ୍ଥାନ ପଢ଼ିହେଲା ନାହିଁ। ସ୍ଥାନ ଆକ୍ସେସ୍ ଅନୁମତି ଦେଇ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "Enter both coordinates to see the office on a map.": "ମାନଚିତ୍ରରେ କାର୍ଯ୍ୟାଳୟ ଦେଖିବାକୁ ଉଭୟ ସ୍ଥାନାଙ୍କ ଦିଅନ୍ତୁ।",
  "Office location": "କାର୍ଯ୍ୟାଳୟ ସ୍ଥାନ",
  "Open in OpenStreetMap": "OpenStreetMap ରେ ଖୋଲନ୍ତୁ",
  "the allowed": "ଅନୁମତିପ୍ରାପ୍ତ",
  "The pin is where punches are measured from. Employees must be within {radius} m of it.": "ପିନ୍ ହେଉଛି ସେହି ସ୍ଥାନ ଯେଉଁଠୁ ପଞ୍ଚ୍ ମପାଯାଏ। କର୍ମଚାରୀମାନେ ଏହାର {radius} m ମଧ୍ୟରେ ରହିବା ଆବଶ୍ୟକ।",
  "This browser cannot share its location.": "ଏହି ବ୍ରାଉଜର୍ ତାହାର ସ୍ଥାନ ଜଣାଇପାରିବ ନାହିଁ।",
  "Use my current location": "ମୋ ବର୍ତ୍ତମାନ ସ୍ଥାନ ବ୍ୟବହାର କରନ୍ତୁ",
  "— only one on file, used automatically": "— ଫାଇଲରେ କେବଳ ଗୋଟିଏ ଅଛି, ସ୍ୱୟଂଚାଳିତ ଭାବେ ବ୍ୟବହୃତ",
  "{stateName} has {count} GST registrations. Pick the one this office uses.": "{stateName} ରେ {count} ଟି GST ପଞ୍ଜୀକରଣ ଅଛି। ଏହି କାର୍ଯ୍ୟାଳୟ ବ୍ୟବହାର କରୁଥିବାଟି ବାଛନ୍ତୁ।",
  "Add one in Company Profile": "କମ୍ପାନୀ ପ୍ରୋଫାଇଲ୍ ରେ ଗୋଟିଏ ଯୋଗ କରନ୍ତୁ",
  "City": "ସହର",
