  "State/Region": "ରାଜ୍ୟ/ଅଞ୍ଚଳ",
  "There is no GST registration for": "ଏଥିପାଇଁ କୌଣସି GST ପଞ୍ଜୀକରଣ ନାହିଁ:",
  "yet. This office will need one.": "ଏପର୍ଯ୍ୟନ୍ତ। ଏହି କାର୍ଯ୍ୟାଳୟକୁ ଗୋଟିଏ ଆବଶ୍ୟକ ହେବ।",
  "{branchName} was created and its Company Code Admin was assigned.": "{branchName} ସୃଷ୍ଟି ହେଲା ଏବଂ ଏହାର କମ୍ପାନୀ କୋଡ୍ ଆଡମିନ୍ ନିଯୁକ୍ତ ହେଲେ।",
  "{branchName} was created and its Company Code Admin was invited by email.": "{branchName} ସୃଷ୍ଟି ହେଲା ଏବଂ ଏହାର କମ୍ପାନୀ କୋଡ୍ ଆଡମିନ୍ ଙ୍କୁ ଇମେଲ୍ ଦ୍ୱାରା ଆମନ୍ତ୍ରଣ କରାଗଲା।",
  "{branchName} was created, but assigning its Company Code Admin failed: {reason} — use the Employees page instead.": "{branchName} ସୃଷ୍ଟି ହେଲା, କିନ୍ତୁ ଏହାର କମ୍ପାନୀ କୋଡ୍ ଆଡମିନ୍ ନିଯୁକ୍ତି ବିଫଳ ହେଲା: {reason} — ଏହା ବଦଳରେ କର୍ମଚାରୀ ପୃଷ୍ଠା ବ୍ୟବହାର କରନ୍ତୁ।",
  "{branchName} was updated and its Company Code Admin was assigned.": "{branchName} ଅପଡେଟ୍ ହେଲା ଏବଂ ଏହାର କମ୍ପାନୀ କୋଡ୍ ଆଡମିନ୍ ନିଯୁକ୍ତ ହେଲେ।",
  "{branchName} was updated and its Company Code Admin was invited by email.": "{branchName} ଅପଡେଟ୍ ହେଲା ଏବଂ ଏହାର କମ୍ପାନୀ କୋଡ୍ ଆଡମିନ୍ ଙ୍କୁ ଇମେଲ୍ ଦ୍ୱାରା ଆମନ୍ତ୍ରଣ କରାଗଲା।",
  "{branchName} was updated, but assigning its Company Code Admin failed: {reason} — use the Employees page instead.": "{branchName} ଅପଡେଟ୍ ହେଲା, କିନ୍ତୁ ଏହାର କମ୍ପାନୀ କୋଡ୍ ଆଡମିନ୍ ନିଯୁକ୍ତି ବିଫଳ ହେଲା: {reason} — ଏହା ବଦଳରେ କର୍ମଚାରୀ ପୃଷ୍ଠା ବ୍ୟବହାର କରନ୍ତୁ।",
  "{branchName} was updated.": "{branchName} ଅପଡେଟ୍ ହେଲା।",
  "{stateName} has {matchCount} GST registrations on file — select which one this branch uses.": "{stateName} ପାଇଁ ଫାଇଲରେ {matchCount} ଟି GST ପଞ୍ଜୀକରଣ ଅଛି — ଏହି ଶାଖା କେଉଁଟି ବ୍ୟବହାର କରୁଛି ବାଛନ୍ତୁ।",
  "0, 0 is not a real office location. Enter the office coordinates.": "0, 0 ଏକ ପ୍ରକୃତ କାର୍ଯ୍ୟାଳୟ ସ୍ଥାନ ନୁହେଁ। କାର୍ଯ୍ୟାଳୟର ସ୍ଥାନାଙ୍କ ଦିଅନ୍ତୁ।",
