  "Add New Company Code": "ନୂଆ କମ୍ପାନୀ କୋଡ୍ ଯୋଗ କରନ୍ତୁ",
  "Address is required.": "ଠିକଣା ଆବଶ୍ୟକ।",
  "Allowed radius is required.": "ଅନୁମତିପ୍ରାପ୍ତ ବ୍ୟାସାର୍ଦ୍ଧ ଆବଶ୍ୟକ।",
  "Allowed radius must be between 10 and 5000 metres.": "ଅନୁମତିପ୍ରାପ୍ତ ବ୍ୟାସାର୍ଦ୍ଧ 10 ରୁ 5000 ମିଟର ମଧ୍ୟରେ ହେବା ଆବଶ୍ୟକ।",
  "Both latitude and longitude must be provided together.": "ଅକ୍ଷାଂଶ ଓ ଦ୍ରାଘିମା ଉଭୟ ଏକାଠି ଦେବାକୁ ହେବ।",
  "Branch code could not be generated. Try re-selecting the city.": "ଶାଖା କୋଡ୍ ପ୍ରସ୍ତୁତ ହୋଇପାରିଲା ନାହିଁ। ସହର ପୁଣି ବାଛି ଚେଷ୍ଟା କରନ୍ତୁ।",
