  "Complete the Company Code Admin details, or clear them to save without an admin.": "କମ୍ପାନୀ କୋଡ୍ ଆଡମିନ୍ ବିବରଣୀ ପୂରଣ କରନ୍ତୁ, କିମ୍ବା ଆଡମିନ୍ ବିନା ସଞ୍ଚୟ କରିବାକୁ ସେଗୁଡ଼ିକ ଖାଲି କରନ୍ତୁ।",
