  "State": "ରାଜ୍ୟ",
  "This candidate came from the recruitment pipeline. You can assign an assessment for their onboarding period, or leave blank to skip.": "ଏହି ପ୍ରାର୍ଥୀ ନିଯୁକ୍ତି ପ୍ରକ୍ରିୟାରୁ ଆସିଛନ୍ତି। ଆପଣ ସେମାନଙ୍କ ଅନବୋର୍ଡିଂ ଅବଧି ପାଇଁ ଏକ ମୂଲ୍ୟାଙ୍କନ ନିଯୁକ୍ତ କରିପାରିବେ, କିମ୍ବା ଛାଡ଼ିବାକୁ ଖାଲି ରଖନ୍ତୁ।",
