  "Nominees are chosen from this list, and the parents' names on step 1 are filled from it. Add family before setting nominations.": "ମନୋନୀତ ବ୍ୟକ୍ତି ଏହି ତାଲିକାରୁ ବଛାଯାଆନ୍ତି, ଏବଂ ପ୍ରଥମ ପଦକ୍ଷେପରେ ଥିବା ପିତାମାତାଙ୍କ ନାମ ଏଥିରୁ ପୂରଣ ହୁଏ। ମନୋନୟନ ସେଟ୍ କରିବା ପୂର୍ବରୁ ପରିବାର ଯୋଗ କରନ୍ତୁ।",
  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "ଘରୋଇ ନିଯୁକ୍ତିଦାତା ପାଇଁ ଆବଶ୍ୟକ ନୁହେଁ। କେବଳ ସେଠାରେ ସଂଗ୍ରହ କରନ୍ତୁ ଯେଉଁଠି ସରକାରୀ, PSU କିମ୍ବା ଅନୁଦାନପ୍ରାପ୍ତ ପ୍ରତିଷ୍ଠାନକୁ ଏହା ରିପୋର୍ଟ କରିବାକୁ ପଡ଼ିବ, କିମ୍ବା ରାଜ୍ୟ ପ୍ରୋତ୍ସାହନ ଯୋଜନା ଏହା ଆବଶ୍ୟକ କରେ। ସ୍ୱୟଂ-ଘୋଷିତ, ଏବଂ ରିପୋର୍ଟିଂ ମ୍ୟାନେଜରଙ୍କଠାରୁ ଲୁଚାଯାଇଛି।",
