  "Required for EPF Form 2. Nominees are picked from the family list, so a name is only typed once. Each scheme should total 100%.": "EPF ଫର୍ମ 2 ପାଇଁ ଆବଶ୍ୟକ। ମନୋନୀତ ବ୍ୟକ୍ତି ପରିବାର ତାଲିକାରୁ ବଛାଯାଆନ୍ତି, ତେଣୁ ନାମ କେବଳ ଥରେ ଲେଖିବାକୁ ପଡ଼େ। ପ୍ରତ୍ୟେକ ଯୋଜନାର ମୋଟ 100% ହେବା ଉଚିତ।",
