  "Monthly amounts use the selected salary structure and effective date. Enabled structure components appear here; statutory contributions and deductions remain governed by payroll eligibility and statutory rules.": "ମାସିକ ରାଶି ବଛାଯାଇଥିବା ଦରମା ଗଠନ ଓ କାର୍ଯ୍ୟକାରୀ ତାରିଖ ବ୍ୟବହାର କରେ। ସକ୍ରିୟ ଗଠନ ଅଂଶ ଏଠାରେ ଦେଖାଯାଏ; ବିଧିବଦ୍ଧ ଅଂଶଦାନ ଓ କଟୌତି ପେରୋଲ୍ ଯୋଗ୍ୟତା ଓ ବିଧିବଦ୍ଧ ନିୟମ ଦ୍ୱାରା ପରିଚାଳିତ ହୁଏ।",
  "No pay record exists for this employee yet.": "ଏହି କର୍ମଚାରୀଙ୍କ ପାଇଁ ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ଦରମା ରେକର୍ଡ ନାହିଁ।",
  "No salary structure applies to this employee. Add or activate one in Settings → Payroll Configuration → Salary Structures; pay components come from it.": "ଏହି କର୍ମଚାରୀଙ୍କ ପାଇଁ କୌଣସି ଦରମା ଗଠନ ଲାଗୁ ହେଉନାହିଁ। ସେଟିଂସ୍ → ପେରୋଲ୍ ବିନ୍ୟାସ → ଦରମା ଗଠନରେ ଗୋଟିଏ ଯୋଗ କିମ୍ବା ସକ୍ରିୟ କରନ୍ତୁ; ଦରମା ଅଂଶ ଏଥିରୁ ଆସେ।",
