  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "ଏହି ଖାତାର ଫାଇଲରେ କୌଣସି କର୍ମଚାରୀ ରେକର୍ଡ ନାହିଁ (କୌଣସି କର୍ମଚାରୀ ନମ୍ବର ଦିଆଯାଇନାହିଁ), ତେଣୁ ତଳେ ଥିବା ନିଯୁକ୍ତି, ଦରମା, ବିଧିବଦ୍ଧ ଓ ଇତିହାସ ବିବରଣୀ ଉପଲବ୍ଧ ନାହିଁ। ଯେଉଁ ଆଡମିନ୍/ସିଷ୍ଟମ୍ ଲଗଇନ୍ କେବେ କର୍ମଚାରୀ ଭାବେ ଅନବୋର୍ଡ ହୋଇନାହିଁ, ତା' ପାଇଁ ଏହା ଆଶାକୃତ — ସମ୍ପୂର୍ଣ୍ଣ ରେକର୍ଡ ଦେଖିବାକୁ ଅନବୋର୍ଡ ହୋଇଥିବା କର୍ମଚାରୀ ଭାବେ ସାଇନ୍ ଇନ୍ କରନ୍ତୁ।",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "ଏହି କର୍ମଚାରୀ ଏକ ବ୍ୟାଙ୍କ ବିବରଣୀ ପରିବର୍ତ୍ତନ ଦାଖଲ କରିଛନ୍ତି ଯାହା ଆପଣଙ୍କ ସମୀକ୍ଷା ଅପେକ୍ଷାରେ — ଆପଣ ନିଷ୍ପତ୍ତି ନେବା ପର୍ଯ୍ୟନ୍ତ ସେମାନଙ୍କ ପୂର୍ବ ବିବରଣୀ ପେରୋଲ୍ ପାଇଁ ସକ୍ରିୟ ରହିବ।",
