  "Select a reason.": "ଏକ କାରଣ ବାଛନ୍ତୁ।",
  "Select an org unit": "ଏକ ସଂଗଠନ ୟୁନିଟ୍ ବାଛନ୍ତୁ",
  "Start a Hire action. HR completes the hiring form here, so this employee will go directly to their dashboard after their first password change rather than receiving the self-service onboarding wizard.": "ଏକ ନିଯୁକ୍ତି କାର୍ଯ୍ୟ ଆରମ୍ଭ କରନ୍ତୁ। HR ଏଠାରେ ନିଯୁକ୍ତି ଫର୍ମ ପୂରଣ କରନ୍ତି, ତେଣୁ ଏହି କର୍ମଚାରୀ ସ୍ୱୟଂ-ସେବା ଅନବୋର୍ଡିଂ ୱିଜାର୍ଡ ପାଇବା ବଦଳରେ ପ୍ରଥମ ପାସୱାର୍ଡ ବଦଳାଇବା ପରେ ସିଧା ନିଜ ଡ୍ୟାଶବୋର୍ଡକୁ ଯିବେ।",
  "This becomes the date of joining.": "ଏହା ଯୋଗଦାନ ତାରିଖ ହେବ।",
