  "Loading onboarding history…": "ଅନବୋର୍ଡିଂ ଇତିହାସ ଲୋଡ୍ ହେଉଛି…",
  "No onboarding events recorded for this employee.": "ଏହି କର୍ମଚାରୀଙ୍କ ପାଇଁ କୌଣସି ଅନବୋର୍ଡିଂ ଘଟଣା ରେକର୍ଡ ହୋଇନାହିଁ।",
  "Onboarding ·": "ଅନବୋର୍ଡିଂ ·",
  "Onboarding timeline": "ଅନବୋର୍ଡିଂ ସମୟରେଖା",
  "Resend Onboarding Email": "ଅନବୋର୍ଡିଂ ଇମେଲ୍ ପୁଣି ପଠାନ୍ତୁ",
  "Sending again makes the previous link stop working.": "ପୁଣି ପଠାଇଲେ ପୂର୍ବ ଲିଙ୍ କାମ କରିବା ବନ୍ଦ କରିଦିଏ।",
  "Sending…": "ପଠାଯାଉଛି…",
  "Up to {count} resends per hour.": "ଘଣ୍ଟାକୁ ସର୍ବାଧିକ {count} ଥର ପୁଣି ପଠାଇପାରିବେ।",
