  "Record outcomes against each goal, with evidence that your manager can verify.": "ପ୍ରତ୍ୟେକ ଲକ୍ଷ୍ୟ ବିପରୀତରେ ଫଳାଫଳ ଦର୍ଜ କରନ୍ତୁ, ଆପଣଙ୍କ ମ୍ୟାନେଜର ଯାଞ୍ଚ କରିପାରିବେ ଏପରି ପ୍ରମାଣ ସହିତ।",
