  "Personal, employment, pay, statutory, leave and audit details": "ବ୍ୟକ୍ତିଗତ, ନିଯୁକ୍ତି, ଦରମା, ସାଂବିଧାନିକ, ଛୁଟି ଓ ଅଡିଟ୍ ବିବରଣୀ",
  "Profile controls": "ପ୍ରୋଫାଇଲ୍ ନିୟନ୍ତ୍ରଣ",
  "Review official fields, then open the full record for all sections.": "ସରକାରୀ ଫିଲ୍ଡ ଦେଖନ୍ତୁ, ତା'ପରେ ସମସ୍ତ ବିଭାଗ ପାଇଁ ସମ୍ପୂର୍ଣ୍ଣ ରେକର୍ଡ ଖୋଲନ୍ତୁ।",
  "Review your official record or update your contact details.": "ଆପଣଙ୍କ ସରକାରୀ ରେକର୍ଡ ଦେଖନ୍ତୁ କିମ୍ବା ଯୋଗାଯୋଗ ବିବରଣୀ ଅଦ୍ୟତନ କରନ୍ତୁ।",
  "Submit a change for HR to review and apply": "HR ସମୀକ୍ଷା କରି ଲାଗୁ କରିବା ପାଇଁ ଏକ ପରିବର୍ତ୍ତନ ଦାଖଲ କରନ୍ତୁ",
  "The same employee record and layout used by Admin, with self-service permissions.": "ଆଡମିନ୍ ବ୍ୟବହାର କରୁଥିବା ସମାନ କର୍ମଚାରୀ ରେକର୍ଡ ଓ ବିନ୍ୟାସ, ସ୍ୱୟଂ-ସେବା ଅନୁମତି ସହିତ।",
  "View employee record": "କର୍ମଚାରୀ ରେକର୍ଡ ଦେଖନ୍ତୁ",
  "WORK EMAIL": "କାମ ଇମେଲ୍",
  "WORK LOCATION": "କାମ ସ୍ଥାନ",
  "{days} days": "{days} ଦିନ",
  "Describe your reason": "ଆପଣଙ୍କ କାରଣ ବର୍ଣ୍ଣନା କରନ୍ତୁ",
  "Handover notes": "ହସ୍ତାନ୍ତର ଟିପ୍ପଣୀ",
  "Key responsibilities and handover plan": "ମୁଖ୍ୟ ଦାୟିତ୍ୱ ଓ ହସ୍ତାନ୍ତର ଯୋଜନା",
  "Please describe your reason in at least 10 characters.": "ଦୟାକରି ଆପଣଙ୍କ କାରଣ ଅତିକମ୍ରେ 10 ଅକ୍ଷରରେ ବର୍ଣ୍ଣନା କରନ୍ତୁ।",
  "Please select your proposed last day.": "ଦୟାକରି ଆପଣଙ୍କ ପ୍ରସ୍ତାବିତ ଶେଷ ଦିନ ବାଛନ୍ତୁ।",
  "Resignation request": "ଇସ୍ତଫା ଅନୁରୋଧ",
  "Submit Resignation": "ଇସ୍ତଫା ଦାଖଲ କରନ୍ତୁ",
  "Submit this resignation request?": "ଏହି ଇସ୍ତଫା ଅନୁରୋଧ ଦାଖଲ କରିବେ?",
  "This submits a formal resignation with a proposed last day of {lastDay} ({noticePeriodDays}-day notice) for HR approval.": "ଏହା HR ଅନୁମୋଦନ ପାଇଁ {lastDay} ପ୍ରସ୍ତାବିତ ଶେଷ ଦିନ ({noticePeriodDays}-ଦିନିଆ ନୋଟିସ୍) ସହ ଏକ ଆନୁଷ୍ଠାନିକ ଇସ୍ତଫା ଦାଖଲ କରେ।",
  "Your proposed last day cannot be in the past.": "ଆପଣଙ୍କ ପ୍ରସ୍ତାବିତ ଶେଷ ଦିନ ଅତୀତରେ ହୋଇପାରିବ ନାହିଁ।",
  "I declare that the information given above is true and complete, and I will submit proofs when payroll asks for them.": "ମୁଁ ଘୋଷଣା କରୁଛି ଯେ ଉପରେ ଦିଆଯାଇଥିବା ସୂଚନା ସତ୍ୟ ଓ ସମ୍ପୂର୍ଣ୍ଣ, ଏବଂ ପେରୋଲ୍ ମାଗିଲେ ମୁଁ ପ୍ରମାଣ ଦାଖଲ କରିବି।",
  "Loading form…": "ଫର୍ମ ଲୋଡ୍ ହେଉଛି…",
  "No investments or rent to declare under the new regime. Switch to the old regime if you want to claim deductions.": "ନୂଆ ବ୍ୟବସ୍ଥାରେ ଘୋଷଣା କରିବାକୁ କୌଣସି ବିନିଯୋଗ କିମ୍ବା ଭଡ଼ା ନାହିଁ। କଟୌତି ଦାବି କରିବାକୁ ଚାହିଁଲେ ପୁରୁଣା ବ୍ୟବସ୍ଥାକୁ ବଦଳାନ୍ତୁ।",
  "Please confirm that the information you have declared is correct.": "ଦୟାକରି ଆପଣ ଘୋଷଣା କରିଥିବା ସୂଚନା ସଠିକ୍ ବୋଲି ନିଶ୍ଚିତ କରନ୍ତୁ।",
  "Submit for review": "ସମୀକ୍ଷା ପାଇଁ ଦାଖଲ କରନ୍ତୁ",
  "Tax declaration — FY {year}": "କର ଘୋଷଣା — FY {year}",
  "Tell payroll what you plan to claim this year so the right tax is deducted each month. You can submit the proofs (receipts, certificates) item by item on the Tax page after you submit.": "ଚଳିତ ବର୍ଷ ଆପଣ କଣ ଦାବି କରିବାକୁ ଯୋଜନା କରୁଛନ୍ତି ପେରୋଲ୍ କୁ ଜଣାନ୍ତୁ, ଯାହା ଫଳରେ ପ୍ରତି ମାସ ସଠିକ୍ କର କଟାଯିବ। ଦାଖଲ ପରେ ଆପଣ କର ପୃଷ୍ଠାରେ ପ୍ରମାଣ (ରସିଦ, ପ୍ରମାଣପତ୍ର) ଗୋଟି ଗୋଟି କରି ଦାଖଲ କରିପାରିବେ।",
  "The form is still loading.": "ଫର୍ମ ଏପର୍ଯ୍ୟନ୍ତ ଲୋଡ୍ ହେଉଛି।",
