  "Home loan lender's name": "ଗୃହ ଋଣଦାତାଙ୍କ ନାମ",
  "I, my spouse or a child is a senior citizen (60+)": "ମୁଁ, ମୋ ଜୀବନସାଥୀ କିମ୍ବା ସନ୍ତାନ ଜଣେ ବରିଷ୍ଠ ନାଗରିକ (60+)",
  "Lender's PAN": "ଋଣଦାତାଙ୍କ PAN",
