  "New regime: only the standard deduction applies, so there is nothing else to claim.": "ନୂଆ ବ୍ୟବସ୍ଥା: କେବଳ ମାନକ କଟୌତି ଲାଗୁ ହୁଏ, ତେଣୁ ଆଉ କିଛି ଦାବି କରିବାକୁ ନାହିଁ।",
