  "No deductions declared yet.": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି କଟୌତି ଘୋଷଣା ହୋଇନାହିଁ।",
  "Rent declared — your HRA exemption is worked out by payroll from your salary when it is processed.": "ଭଡ଼ା ଘୋଷିତ — ଦରମା ପ୍ରକ୍ରିୟା ହେବା ସମୟରେ ପେରୋଲ୍ ଆପଣଙ୍କ ଦରମାରୁ ଆପଣଙ୍କ HRA ଛାଡ଼ ହିସାବ କରେ।",
  "Saved as a draft — not sent to payroll yet": "ଡ୍ରାଫ୍ଟ ଭାବେ ସଞ୍ଚିତ — ଏପର୍ଯ୍ୟନ୍ତ ପେରୋଲ୍ କୁ ପଠାଯାଇନାହିଁ",
  "Submitted {date}": "{date} ରେ ଦାଖଲ ହୋଇଛି",
  "Submitted declarations are reviewed by Payroll Operations. Proofs go under Documents → Tax proof.": "ଦାଖଲ ଘୋଷଣା ପେରୋଲ୍ ଅପରେସନ୍ସ ଦ୍ୱାରା ସମୀକ୍ଷା ହୁଏ। ପ୍ରମାଣ ଦଲିଲ → କର ପ୍ରମାଣ ଅଧୀନରେ ଯାଏ।",
  "Total deduction after limits": "ସୀମା ପରେ ମୋଟ କଟୌତି",
  "Approve this tax declaration?": "ଏହି କର ଘୋଷଣା ଅନୁମୋଦନ କରିବେ?",
  "Failed to approve this declaration. Please try again.": "ଏହି ଘୋଷଣା ଅନୁମୋଦିତ ହେଲା ନାହିଁ। ଦୟାକରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "HR review queue": "HR ସମୀକ୍ଷା ଧାଡ଼ି",
  "No declarations yet": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ଘୋଷଣା ନାହିଁ",
  "Regime": "ବ୍ୟବସ୍ଥା",
  "This locks {name}'s FY {year} declaration ({regime}, {deductions} deductions after limits) — they will no longer be able to change their regime or declared investments for this financial year.": "ଏହା {name} ଙ୍କ FY {year} ଘୋଷଣାକୁ ବନ୍ଦ କରିଦେବ ({regime}, ସୀମା ପରେ {deductions} କଟୌତି) — ଏହି ଆର୍ଥିକ ବର୍ଷ ପାଇଁ ସେମାନେ ଆଉ ସେମାନଙ୍କ ବ୍ୟବସ୍ଥା କିମ୍ବା ଘୋଷିତ ବିନିଯୋଗ ବଦଳାଇପାରିବେ ନାହିଁ।",
  "Income from a previous employer": "ପୂର୍ବ ନିଯୁକ୍ତିଦାତାଙ୍କଠାରୁ ଆୟ",
  "Joined this year? Enter what your previous employer paid you and the tax they deducted this financial year (from your Form 16 or last payslip). Leave blank if this is your first job this year.": "ଚଳିତ ବର୍ଷ ଯୋଗ ଦେଇଛନ୍ତି? ଏହି ଆର୍ଥିକ ବର୍ଷରେ ଆପଣଙ୍କ ପୂର୍ବ ନିଯୁକ୍ତିଦାତା ଆପଣଙ୍କୁ କେତେ ଦେଇଛନ୍ତି ଏବଂ କେତେ କର କାଟିଛନ୍ତି ଲେଖନ୍ତୁ (ଆପଣଙ୍କ ଫର୍ମ 16 କିମ୍ବା ଶେଷ ଦରମା ସ୍ଲିପ୍ ରୁ)। ଏହା ଚଳିତ ବର୍ଷର ଆପଣଙ୍କ ପ୍ରଥମ ଚାକିରି ହୋଇଥିଲେ ଖାଲି ଛାଡ଼ନ୍ତୁ।",
  "Previous employer": "ପୂର୍ବ ନିଯୁକ୍ତିଦାତା",
  "Tax deducted (TDS) (₹)": "କଟାଯାଇଥିବା କର (TDS) (₹)",
  "Taxable income paid (₹)": "ଦିଆଯାଇଥିବା କରଯୋଗ୍ୟ ଆୟ (₹)",
  "· No. {number}": "· ନଂ. {number}",
  "Claimed {amount}": "{amount} ଦାବି କରାଯାଇଛି",
  "Declare your investments first, then upload the proofs here.": "ପ୍ରଥମେ ଆପଣଙ୍କ ବିନିଯୋଗ ଘୋଷଣା କରନ୍ତୁ, ତା'ପରେ ଏଠାରେ ପ୍ରମାଣ ଅପଲୋଡ୍ କରନ୍ତୁ।",
  "Declared {declared} · eligible {eligible}": "ଘୋଷିତ {declared} · ଯୋଗ୍ୟ {eligible}",
