  "No proofs needed under the new regime": "ନୂଆ ବ୍ୟବସ୍ଥାରେ କୌଣସି ପ୍ରମାଣ ଦରକାର ନାହିଁ",
  "NOT UPLOADED": "ଅପଲୋଡ୍ ହୋଇନାହିଁ",
  "Nothing to prove yet": "ଏପର୍ଯ୍ୟନ୍ତ ପ୍ରମାଣ କରିବାକୁ କିଛି ନାହିଁ",
  "Only the old regime has deductions that need proof.": "କେବଳ ପୁରୁଣା ବ୍ୟବସ୍ଥାରେ ପ୍ରମାଣ ଆବଶ୍ୟକ କଟୌତି ଅଛି।",
  "Upload": "ଅପଲୋଡ୍ କରନ୍ତୁ",
  "Upload a receipt or certificate for each item you claimed. Payroll verifies them before they count in full.": "ଆପଣ ଦାବି କରିଥିବା ପ୍ରତ୍ୟେକ ଆଇଟମ୍ ପାଇଁ ଏକ ରସିଦ କିମ୍ବା ପ୍ରମାଣପତ୍ର ଅପଲୋଡ୍ କରନ୍ତୁ। ସମ୍ପୂର୍ଣ୍ଣ ଗଣାଯିବା ପୂର୍ବରୁ ପେରୋଲ୍ ସେଗୁଡ଼ିକୁ ଯାଞ୍ଚ କରେ।",
