  "Please choose the proof document.": "ଦୟାକରି ପ୍ରମାଣ ଦଲିଲ ବାଛନ୍ତୁ।",
  "Policy / account / receipt number (optional)": "ପଲିସି / ଖାତା / ରସିଦ ନମ୍ବର (ବୈକଳ୍ପିକ)",
  "Proof needed: {proof}.": "ପ୍ରମାଣ ଆବଶ୍ୟକ: {proof}।",
