  "Filter employees by Face ID status": "Face ID ସ୍ଥିତି ଅନୁସାରେ କର୍ମଚାରୀ ଫିଲ୍ଟର୍ କରନ୍ତୁ",
  "of {total} employees registered": "{total} କର୍ମଚାରୀଙ୍କ ମଧ୍ୟରୁ ପଞ୍ଜୀକୃତ",
  "Show {count} not completed": "{count} ଅସମ୍ପୂର୍ଣ୍ଣ ଦେଖାନ୍ତୁ",
  "Pending requests": "ବାକି ଅନୁରୋଧ",
  "Register or update an employee's Face ID in person. It is approved immediately.": "ଜଣେ କର୍ମଚାରୀଙ୍କ Face ID ବ୍ୟକ୍ତିଗତ ଭାବେ ପଞ୍ଜୀକରଣ କିମ୍ବା ଅଦ୍ୟତନ କରନ୍ତୁ। ଏହା ତୁରନ୍ତ ଅନୁମୋଦିତ ହୁଏ।",
  "{name}'s face ID is approved and active immediately — no further review needed.": "{name} ଙ୍କ Face ID ତୁରନ୍ତ ଅନୁମୋଦିତ ଓ ସକ୍ରିୟ ହୁଏ — ଆଉ ସମୀକ୍ଷା ଆବଶ୍ୟକ ନାହିଁ।",
  "Camera access denied": "କ୍ୟାମେରା ଆକ୍ସେସ୍ ଅସ୍ୱୀକୃତ",
  "Capture wasn't clear enough": "କ୍ୟାପଚର୍ ଯଥେଷ୍ଟ ସ୍ପଷ୍ଟ ନଥିଲା",
  "Couldn't confirm they're live": "ସେମାନେ ଜୀବନ୍ତ ବୋଲି ନିଶ୍ଚିତ କରିହେଲା ନାହିଁ",
  "Downloading face models (first time only)…": "ଫେସ୍ ମଡେଲ୍ ଡାଉନଲୋଡ୍ ହେଉଛି (କେବଳ ପ୍ରଥମ ଥର)…",
  "Face ID registered!": "Face ID ପଞ୍ଜୀକୃତ ହେଲା!",
  "Have the employee sit in front of this camera, then start — a quick liveness check confirms it's really them before it's saved.": "କର୍ମଚାରୀଙ୍କୁ ଏହି କ୍ୟାମେରା ସାମନାରେ ବସାନ୍ତୁ, ତା'ପରେ ଆରମ୍ଭ କରନ୍ତୁ — ସଞ୍ଚୟ ପୂର୍ବରୁ ଏକ ଶୀଘ୍ର ଜୀବନ୍ତତା ଯାଞ୍ଚ ନିଶ୍ଚିତ କରେ ଯେ ସେ ହିଁ ଅଟନ୍ତି।",
  "Please allow camera access in the browser prompt.": "ଦୟାକରି ବ୍ରାଉଜର୍ ପ୍ରମ୍ପ୍ଟରେ କ୍ୟାମେରା ଆକ୍ସେସ୍ ଅନୁମତି ଦିଅନ୍ତୁ।",
  "Please try again.": "ଦୟାକରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "Preparing face recognition": "ଫେସ୍ ସ୍ୱୀକୃତି ପ୍ରସ୍ତୁତ ହେଉଛି",
  "Register {name}'s face": "{name} ଙ୍କ ମୁହଁ ପଞ୍ଜୀକରଣ କରନ୍ତୁ",
  "Register Face ID — {name}": "Face ID ପଞ୍ଜୀକରଣ — {name}",
  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "Face ID ପଞ୍ଜୀକରଣ ପାଇଁ କ୍ୟାମେରା ଆକ୍ସେସ୍ ଆବଶ୍ୟକ। ଆପଣଙ୍କ ବ୍ରାଉଜର୍ ସେଟିଂସ୍ ରେ ଏହି ସାଇଟ୍ ପାଇଁ ଅନୁମତି ଦିଅନ୍ତୁ, ତା'ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "Registering face ID…": "Face ID ପଞ୍ଜୀକରଣ ହେଉଛି…",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure they're well-lit and centered, then try again.": "ପଞ୍ଜୀକରଣ ପାଇଁ ଏକ ସ୍ୱାଭାବିକ ପଲକ ଓ ମୁଣ୍ଡର ସାମାନ୍ୟ ଘୂର୍ଣ୍ଣନ ଉଭୟ ଆବଶ୍ୟକ, ଏବଂ ଆମେ ସମୟରେ ଦୁହେଁ ଦେଖିପାରିଲୁ ନାହିଁ। ସେମାନେ ଭଲ ଆଲୋକରେ ଓ କେନ୍ଦ୍ରରେ ଅଛନ୍ତି ନିଶ୍ଚିତ କରନ୍ତୁ, ତା'ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "Requesting camera access": "କ୍ୟାମେରା ଆକ୍ସେସ୍ ମାଗାଯାଉଛି",
  "Saving": "ସଞ୍ଚୟ ହେଉଛି",
  "Something went wrong": "କିଛି ଭୁଲ ହୋଇଗଲା",
  "This will replace their currently registered face ID. Position them in front of the camera and start when ready.": "ଏହା ସେମାନଙ୍କ ବର୍ତ୍ତମାନର ପଞ୍ଜୀକୃତ Face ID କୁ ବଦଳାଇଦେବ। ସେମାନଙ୍କୁ କ୍ୟାମେରା ସାମନାରେ ରଖନ୍ତୁ ଏବଂ ପ୍ରସ୍ତୁତ ହେଲେ ଆରମ୍ଭ କରନ୍ତୁ।",
  "Try Again": "ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ",
  "Update {name}'s face": "{name} ଙ୍କ ମୁହଁ ଅଦ୍ୟତନ କରନ୍ତୁ",
  "Update Face ID — {name}": "Face ID ଅଦ୍ୟତନ — {name}",
  "We couldn't get a reliably clear capture — this becomes their permanent face ID reference, so it's worth getting right. Try better lighting and have them hold steady.": "ଆମେ ନିର୍ଭରଯୋଗ୍ୟ ଭାବେ ସ୍ପଷ୍ଟ କ୍ୟାପଚର୍ ପାଇଲୁ ନାହିଁ — ଏହା ସେମାନଙ୍କ ସ୍ଥାୟୀ Face ID ସନ୍ଦର୍ଭ ହେବ, ତେଣୁ ଏହା ଠିକ୍ କରିବା ଜରୁରୀ। ଭଲ ଆଲୋକ ଚେଷ୍ଟା କରନ୍ତୁ ଏବଂ ସେମାନଙ୍କୁ ସ୍ଥିର ରହିବାକୁ କୁହନ୍ତୁ।",
  "Contact an HR administrator if you believe this is a mistake.": "ଏହା ଭୁଲ ବୋଲି ଆପଣ ଭାବୁଥିଲେ HR ଆଡମିନିଷ୍ଟ୍ରେଟରଙ୍କୁ ଯୋଗାଯୋଗ କରନ୍ତୁ।",
  "You don't have permission to manage face ID registrations": "Face ID ପଞ୍ଜୀକରଣ ପରିଚାଳନା କରିବାକୁ ଆପଣଙ୍କର ଅନୁମତି ନାହିଁ",
