  "Address line 1": "ଠିକଣା ଧାଡ଼ି 1",
  "Address line 2": "ଠିକଣା ଧାଡ଼ି 2",
  "Already filled in from the PIN code": "PIN କୋଡ୍ ରୁ ପୂର୍ବରୁ ଭରାଯାଇଛି",
  "Country": "ଦେଶ",
  "CURRENT ADDRESS": "ବର୍ତ୍ତମାନର ଠିକଣା",
  "Enter the 6-digit PIN code first. Suggest fills the state, district and city from it. You can also choose the state, then the district, then pick the PIN code from the list.": "ପ୍ରଥମେ 6-ଅଙ୍କିଆ PIN କୋଡ୍ ଦିଅନ୍ତୁ। \"ପରାମର୍ଶ\" ଏହାରୁ ରାଜ୍ୟ, ଜିଲ୍ଲା ଓ ସହର ଭରିଦିଏ। ଆପଣ ରାଜ୍ୟ, ତା'ପରେ ଜିଲ୍ଲା ବାଛି, ତାଲିକାରୁ PIN କୋଡ୍ ମଧ୍ୟ ବାଛିପାରିବେ।",
  "Fill this in from the PIN code": "PIN କୋଡ୍ ରୁ ଏହା ଭରନ୍ତୁ",
