  "PERMANENT ADDRESS": "ସ୍ଥାୟୀ ଠିକଣା",
  "Permanent address is the same as current": "ସ୍ଥାୟୀ ଠିକଣା ବର୍ତ୍ତମାନର ଠିକଣା ସହ ସମାନ",
  "PIN code": "PIN କୋଡ୍",
  "Street, area": "ରାସ୍ତା, ଅଞ୍ଚଳ",
  "Suggest": "ପରାମର୍ଶ",
  "That PIN code has no area name to suggest. Type the city.": "ସେହି PIN କୋଡ୍ ପାଇଁ ପରାମର୍ଶ ଦେବାକୁ କୌଣସି ଅଞ୍ଚଳ ନାମ ନାହିଁ। ସହର ଲେଖନ୍ତୁ।",
  "We could not find PIN code {pincode}. Check it, or choose the state and district yourself.": "ଆମେ PIN କୋଡ୍ {pincode} ପାଇଲୁ ନାହିଁ। ଏହାକୁ ଯାଞ୍ଚ କରନ୍ତୁ, କିମ୍ବା ନିଜେ ରାଜ୍ୟ ଓ ଜିଲ୍ଲା ବାଛନ୍ତୁ।",
  "Estimating…": "ଆକଳନ ହେଉଛି…",
