  "Ready to hire": "ନିଯୁକ୍ତି ପାଇଁ ପ୍ରସ୍ତୁତ",
  "Record completeness": "ରେକର୍ଡ ସମ୍ପୂର୍ଣ୍ଣତା",
  "STATUTORY & ACCOUNTS": "ସାଂବିଧାନିକ ଓ ଖାତା",
  "The new hire cannot register it themselves.": "ନୂଆ ନିଯୁକ୍ତ ବ୍ୟକ୍ତି ନିଜେ ଏହାକୁ ପଞ୍ଜୀକରଣ କରିପାରିବେ ନାହିଁ।",
  "The new hire registers their Face ID from their Profile page, and HR approves it on": "ନୂଆ ନିଯୁକ୍ତ ବ୍ୟକ୍ତି ସେମାନଙ୍କ ପ୍ରୋଫାଇଲ୍ ପୃଷ୍ଠାରୁ Face ID ପଞ୍ଜୀକରଣ କରନ୍ତି, ଏବଂ HR ଏହାକୁ ଅନୁମୋଦନ କରନ୍ତି",
  "The new hire registers their own Face ID from their Profile page; it is active immediately.": "ନୂଆ ନିଯୁକ୍ତ ବ୍ୟକ୍ତି ସେମାନଙ୍କ ପ୍ରୋଫାଇଲ୍ ପୃଷ୍ଠାରୁ ନିଜର Face ID ପଞ୍ଜୀକରଣ କରନ୍ତି; ଏହା ତୁରନ୍ତ ସକ୍ରିୟ ହୁଏ।",
  "the record can still be created in Onboarding status.": "ରେକର୍ଡ ଏବେ ବି ଅନବୋର୍ଡିଂ ସ୍ଥିତିରେ ସୃଷ୍ଟି କରାଯାଇପାରିବ।",
  "The record is created in Onboarding status. Optional details (father/mother's name, non-required documents) can still be finished afterward.": "ରେକର୍ଡ ଅନବୋର୍ଡିଂ ସ୍ଥିତିରେ ସୃଷ୍ଟି ହୁଏ। ବୈକଳ୍ପିକ ବିବରଣୀ (ପିତା/ମାତାଙ୍କ ନାମ, ଅନାବଶ୍ୟକ ଦଲିଲ) ପରେ ମଧ୍ୟ ସମ୍ପୂର୍ଣ୍ଣ କରାଯାଇପାରିବ।",
  "Until it is done they cannot clock in on the web.": "ଏହା ନହେବା ପର୍ଯ୍ୟନ୍ତ ସେମାନେ ୱେବ୍ ରେ କ୍ଲକ୍-ଇନ୍ କରିପାରିବେ ନାହିଁ।",
  "Until then they can still clock in from the office; those punches are flagged for HR.": "ସେତେବେଳ ପର୍ଯ୍ୟନ୍ତ ସେମାନେ ଅଫିସରୁ କ୍ଲକ୍-ଇନ୍ କରିପାରିବେ; ସେହି ପଞ୍ଚ୍ ଗୁଡ଼ିକ HR ପାଇଁ ଚିହ୍ନିତ ହୁଏ।",
  "Apply selected": "ବଛାଯାଇଥିବା ଲାଗୁ କରନ୍ତୁ",
  "Choose a PDF, JPG or PNG": "ଏକ PDF, JPG କିମ୍ବା PNG ବାଛନ୍ତୁ",
  "Could not scan this document. Please try again.": "ଏହି ଦଲିଲ ସ୍କାନ୍ ହୋଇପାରିଲା ନାହିଁ। ଦୟାକରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "FOUND IN DOCUMENT": "ଦଲିଲରେ ମିଳିଲା",
  "Scanning…": "ସ୍କାନ୍ ହେଉଛି…",
  "Upload a text-based PDF (an offer letter, ID or resume exported as PDF). This reads the actual text in the document and matches recognizable fields — it does not guess anything not on the page.": "ଏକ ଟେକ୍ସଟ୍-ଆଧାରିତ PDF ଅପଲୋଡ୍ କରନ୍ତୁ (PDF ଭାବେ ଏକ୍ସପୋର୍ଟ କରାଯାଇଥିବା ଅଫର୍ ଲେଟର୍, ID କିମ୍ବା ରିଜ୍ୟୁମ୍)। ଏହା ଦଲିଲରେ ଥିବା ପ୍ରକୃତ ଲେଖା ପଢ଼ି ଚିହ୍ନିହେଉଥିବା ଫିଲ୍ଡ ମିଳାଏ — ପୃଷ୍ଠାରେ ନଥିବା କିଛି ଅନୁମାନ କରେ ନାହିଁ।",
  "10 digits, if available": "10 ଅଙ୍କ, ଯଦି ଉପଲବ୍ଧ",
  "12 digits, if available": "12 ଅଙ୍କ, ଯଦି ଉପଲବ୍ଧ",
  "As printed on the Aadhaar card": "ଆଧାର କାର୍ଡରେ ଛପାଯାଇଥିବା ଅନୁସାରେ",
  "Auto-filled from IFSC, or enter manually": "IFSC ରୁ ସ୍ୱୟଂ ଭରାଯାଏ, କିମ୍ବା ନିଜେ ଦିଅନ୍ତୁ",
  "BANK ACCOUNT": "ବ୍ୟାଙ୍କ ଖାତା",
  "Bank and branch found — filled in below.": "ବ୍ୟାଙ୍କ ଓ ଶାଖା ମିଳିଲା — ତଳେ ଭରାଗଲା।",
