  "You don't assign a head here. Add a position next, then mark it chief.": "ଆପଣ ଏଠାରେ ମୁଖ୍ୟ ନିର୍ଦ୍ଧାରଣ କରନ୍ତି ନାହିଁ। ପରବର୍ତ୍ତୀ ଭାବେ ଏକ ପଦବୀ ଯୋଗ କରନ୍ତୁ, ତା'ପରେ ଏହାକୁ ପ୍ରଧାନ ଚିହ୍ନିତ କରନ୍ତୁ।",
  "{name}'s placement will be closed the day before the new start date and kept in history.": "{name} ଙ୍କ ନିଯୁକ୍ତି ନୂଆ ଆରମ୍ଭ ତାରିଖର ଦିନ ପୂର୍ବରୁ ବନ୍ଦ ହେବ ଏବଂ ଇତିହାସରେ ରହିବ।",
  "Assign holder": "ଧାରକ ନିର୍ଦ୍ଧାରଣ କରନ୍ତୁ",
  "Effective to": "ପର୍ଯ୍ୟନ୍ତ ଲାଗୁ",
  "Effective to can't be before effective from.": "\"ପର୍ଯ୍ୟନ୍ତ ଲାଗୁ\" \"ଠାରୁ ଲାଗୁ\" ପୂର୍ବରୁ ହୋଇପାରିବ ନାହିଁ।",
  "Failed to assign holder.": "ଧାରକ ନିର୍ଦ୍ଧାରଣ ହେଲା ନାହିଁ।",
  "Pick an employee.": "ଜଣେ କର୍ମଚାରୀ ବାଛନ୍ତୁ।",
  "Placing a person on a chief position makes them the unit's head automatically, as of the effective date above. A future-dated start schedules the change without affecting today's holder.": "ଜଣେ ବ୍ୟକ୍ତିଙ୍କୁ ପ୍ରଧାନ ପଦବୀରେ ରଖିଲେ ଉପରୋକ୍ତ ଲାଗୁ ତାରିଖରୁ ସେମାନେ ସ୍ୱୟଂଚାଳିତ ଭାବେ ଇଉନିଟ୍ ର ମୁଖ୍ୟ ହୁଅନ୍ତି। ଭବିଷ୍ୟତ ତାରିଖର ଆରମ୍ଭ ଆଜିର ଧାରକଙ୍କୁ ପ୍ରଭାବିତ ନକରି ପରିବର୍ତ୍ତନ ନିର୍ଦ୍ଧାରିତ କରେ।",
  "Reassign": "ପୁନଃ ନିର୍ଦ୍ଧାରଣ କରନ୍ତୁ",
  "Reassign holder": "ଧାରକ ପୁନଃ ନିର୍ଦ୍ଧାରଣ କରନ୍ତୁ",
  "Select an employee…": "ଜଣେ କର୍ମଚାରୀ ବାଛନ୍ତୁ…",
  " — nothing is deleted, and this can be reversed at any time.": " — କିଛି ଡିଲିଟ୍ ହୁଏ ନାହିଁ, ଏବଂ ଏହାକୁ ଯେକୌଣସି ସମୟରେ ଫେରାଇହେବ।",
  ". Deactivating it does": "। ଏହାକୁ ନିଷ୍କ୍ରିୟ କଲେ",
  ". Vacate it first if that's what you actually want.": "। ଯଦି ଆପଣ ପ୍ରକୃତରେ ତାହା ଚାହାଁନ୍ତି ତେବେ ପ୍ରଥମେ ଏହାକୁ ଖାଲି କରନ୍ତୁ।",
  "chief": "ପ୍ରଧାନ",
  "Deactivate position": "ପଦବୀ ନିଷ୍କ୍ରିୟ କରନ୍ତୁ",
  "Deactivated positions keep their full placement history and stay visible in the tree, tagged": "ନିଷ୍କ୍ରିୟ ପଦବୀ ସେମାନଙ୍କ ସମ୍ପୂର୍ଣ୍ଣ ନିଯୁକ୍ତି ଇତିହାସ ରଖନ୍ତି ଏବଂ ଗଛରେ ଦୃଶ୍ୟମାନ ରହନ୍ତି, ଚିହ୍ନିତ",
  "end their placement or vacate the seat — the position will just show as": "ସେମାନଙ୍କ ନିଯୁକ୍ତି ସମାପ୍ତ କରେ ନାହିଁ କିମ୍ବା ପଦ ଖାଲି କରେ ନାହିଁ — ପଦବୀ କେବଳ ଏହିପରି ଦେଖାଯିବ",
  "Failed to deactivate this position.": "ଏହି ପଦବୀ ନିଷ୍କ୍ରିୟ ହେଲା ନାହିଁ।",
  "not": "ନୁହେଁ",
  "position for {unit}. Deactivating it leaves the unit without a visible head until another position is marked chief.": "{unit} ପାଇଁ ପଦବୀ। ଏହାକୁ ନିଷ୍କ୍ରିୟ କଲେ ଅନ୍ୟ ଏକ ପଦବୀ ପ୍ରଧାନ ଚିହ୍ନିତ ନହେବା ପର୍ଯ୍ୟନ୍ତ ଇଉନିଟ୍ ବିନା ଦୃଶ୍ୟମାନ ମୁଖ୍ୟରେ ରହିବ।",
  "This is the": "ଏହା ହେଉଛି",
  "This position currently has an active holder,": "ଏହି ପଦବୀରେ ବର୍ତ୍ତମାନ ଜଣେ ସକ୍ରିୟ ଧାରକ ଅଛନ୍ତି,",
  "{name} stays the holder through this date. The seat becomes vacant the day after.": "{name} ଏହି ତାରିଖ ପର୍ଯ୍ୟନ୍ତ ଧାରକ ରହିବେ। ତା'ପରଦିନ ପଦ ଖାଲି ହେବ।",
  "Can't be before {date}, when this placement started.": "{date} ପୂର୍ବରୁ ହୋଇପାରିବ ନାହିଁ, ଯେବେ ଏହି ନିଯୁକ୍ତି ଆରମ୍ଭ ହୋଇଥିଲା।",
  "currently held by": "ବର୍ତ୍ତମାନ ଧାରଣ କରିଛନ୍ତି",
