  "Delete the job template \"{name}\"? This can't be undone.": "ଚାକିରି ଟେମ୍ପଲେଟ୍ \"{name}\" ଡିଲିଟ୍ କରିବେ? ଏହାକୁ ଫେରାଇହେବ ନାହିଁ।",
  "Failed to create job template.": "ଚାକିରି ଟେମ୍ପଲେଟ୍ ସୃଷ୍ଟି ହେଲା ନାହିଁ।",
  "Failed to delete job template.": "ଚାକିରି ଟେମ୍ପଲେଟ୍ ଡିଲିଟ୍ ହେଲା ନାହିଁ।",
