  "Manage job templates": "ଚାକିରି ଟେମ୍ପଲେଟ୍ ପରିଚାଳନା କରନ୍ତୁ",
  "No job templates yet.": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ଚାକିରି ଟେମ୍ପଲେଟ୍ ନାହିଁ।",
  "Reusable job titles offered when adding a position. Deactivate a template to stop offering it for new positions without losing history on positions that already use it.": "ପଦବୀ ଯୋଗ କରିବା ସମୟରେ ଦିଆଯାଉଥିବା ପୁନଃବ୍ୟବହାର୍ଯ୍ୟ ଚାକିରି ଶୀର୍ଷକ। ପୂର୍ବରୁ ଏହାକୁ ବ୍ୟବହାର କରୁଥିବା ପଦବୀର ଇତିହାସ ହରାଇ ନଦେଇ ନୂଆ ପଦବୀ ପାଇଁ ଏହାକୁ ଦେବା ବନ୍ଦ କରିବାକୁ ଏକ ଟେମ୍ପଲେଟ୍ ନିଷ୍କ୍ରିୟ କରନ୍ତୁ।",
