  "No org units yet — add one to get started.": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ସଂଗଠନ ଇଉନିଟ୍ ନାହିଁ — ଆରମ୍ଭ କରିବାକୁ ଗୋଟିଏ ଯୋଗ କରନ୍ତୁ।",
