  "Permanently delete \"{name}\"? This can't be undone, and only works if it has never had a holder — if it has any placement history, this will be rejected; deactivate it instead.": "\"{name}\" ସ୍ଥାୟୀ ଭାବେ ଡିଲିଟ୍ କରିବେ? ଏହାକୁ ଫେରାଇହେବ ନାହିଁ, ଏବଂ ଏଥିରେ କେବେ ଧାରକ ନଥିଲେ ହିଁ କାମ କରେ — ଯଦି ଏହାର କୌଣସି ନିଯୁକ୍ତି ଇତିହାସ ଅଛି, ଏହା ପ୍ରତ୍ୟାଖ୍ୟାତ ହେବ; ବଦଳରେ ଏହାକୁ ନିଷ୍କ୍ରିୟ କରନ୍ତୁ।",
