  "Positions with nobody reporting to them and no one they report to. Set 'Reports to' on a position to place it in the chain.": "ଯେଉଁ ପଦବୀକୁ କେହି ରିପୋର୍ଟ କରନ୍ତି ନାହିଁ ଏବଂ ଯେଉଁମାନେ କାହାକୁ ରିପୋର୍ଟ କରନ୍ତି ନାହିଁ। ଏକ ପଦବୀକୁ ଧାରାରେ ରଖିବାକୁ ତା'ର 'ରିପୋର୍ଟ କରିବେ' ସେଟ୍ କରନ୍ତୁ।",
