  "Team manager": "ଦଳ ମ୍ୟାନେଜର",
  "These permissions belong to this position. The current holder receives them; a future holder receives the same access. Permissions do not automatically pass between a manager and their reports. Give each position its own access below.": "ଏହି ଅନୁମତି ଏହି ପଦବୀର। ବର୍ତ୍ତମାନର ଧାରକ ସେଗୁଡ଼ିକ ପାଆନ୍ତି; ଭବିଷ୍ୟତର ଧାରକ ସମାନ ଆକ୍ସେସ୍ ପାଇବେ। ଅନୁମତି ମ୍ୟାନେଜର ଓ ତାଙ୍କ ରିପୋର୍ଟ ମଧ୍ୟରେ ଆପେ ଆପେ ଯାଏ ନାହିଁ। ପ୍ରତ୍ୟେକ ପଦବୀକୁ ତଳେ ନିଜର ଆକ୍ସେସ୍ ଦିଅନ୍ତୁ।",
  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "ଦଳ ମ୍ୟାନେଜର ଚାଲୁ କରିବା ଦ୍ୱାରା ତଳେ ଥିବା ସାଧାରଣ ମ୍ୟାନେଜର ଅନୁମତି (କର୍ମଚାରୀ ଦେଖିବା, ଛୁଟି ଅନୁମୋଦନ, ଉପସ୍ଥିତି ଦେଖିବା) ମଧ୍ୟ ଚିହ୍ନିତ ହୋଇଛି, ଯେପରି ଏହି ପଦବୀରେ 0 ଅନୁମତି ନରହେ। ସଞ୍ଚୟ ପୂର୍ବରୁ ଯାହା ଚାହୁଁନାହାନ୍ତି ତାହା ଅଚିହ୍ନିତ କରନ୍ତୁ।",
