  "Each manager must sign off on their team's attendance": "ପ୍ରତ୍ୟେକ ମ୍ୟାନେଜର ନିଜ ଦଳର ଉପସ୍ଥିତି ଉପରେ ସାଇନ୍ ଅଫ୍ କରିବା ଆବଶ୍ୟକ",
