  "Employer contribution: {amount}": "ନିଯୁକ୍ତିଦାତାଙ୍କ ଅଂଶଦାନ: {amount}",
  "Ensure employees have CTC configured and the cycle was processed in the previous step.": "କର୍ମଚାରୀଙ୍କ CTC ସେଟ୍ ହୋଇଛି ଏବଂ ପୂର୍ବ ପଦକ୍ଷେପରେ ଚକ୍ର ପ୍ରକ୍ରିୟା ହୋଇଛି ବୋଲି ନିଶ୍ଚିତ କରନ୍ତୁ।",
  "ESI Employee": "ESI କର୍ମଚାରୀ",
  "Extras": "ଅତିରିକ୍ତ",
