  "and available for the next payroll run.": "ଏବଂ ପରବର୍ତ୍ତୀ ପେରୋଲ୍ ରନ୍ ପାଇଁ ଉପଲବ୍ଧ।",
  "Any approved expenses already included in this cycle will be": "ଏହି ଚକ୍ରରେ ପୂର୍ବରୁ ଅନ୍ତର୍ଭୁକ୍ତ ଯେକୌଣସି ଅନୁମୋଦିତ ଖର୍ଚ୍ଚ ହେବ",
  "Cancel Payroll Cycle": "ପେରୋଲ୍ ଚକ୍ର ବାତିଲ୍ କରନ୍ତୁ",
