  "e.g. Wrong cycle dates entered, payroll period needs to be restarted…": "ଉଦା. ଭୁଲ ଚକ୍ର ତାରିଖ ଦିଆଯାଇଛି, ପେରୋଲ୍ ଅବଧି ପୁନଃ ଆରମ୍ଭ କରିବାକୁ ପଡ଼ିବ…",
  "Failed to cancel cycle. Please try again.": "ଚକ୍ର ବାତିଲ୍ ହେଲା ନାହିଁ। ଦୟାକରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
