  "Your account is not assigned to a branch. Payroll actions are unavailable until an administrator assigns you to a branch in Settings → Employees.": "ଆପଣଙ୍କ ଖାତା କୌଣସି ଶାଖାକୁ ଦିଆଯାଇନାହିଁ। ଜଣେ ଆଡମିନ୍ ଆପଣଙ୍କୁ ସେଟିଂସ୍ → କର୍ମଚାରୀରେ ଏକ ଶାଖାକୁ ନ ଦେବା ପର୍ଯ୍ୟନ୍ତ ପେରୋଲ୍ କାର୍ଯ୍ୟ ଉପଲବ୍ଧ ନୁହେଁ।",
  "Computed Period Dates": "ଗଣନା ହୋଇଥିବା ଅବଧି ତାରିଖ",
  "Dates are auto-filled from your Payroll Run Settings. Adjust month/year to change them.": "ତାରିଖ ଆପଣଙ୍କ ପେରୋଲ୍ ରନ୍ ସେଟିଂସ୍ ରୁ ଆପେ ଆପେ ଭରାଯାଏ। ବଦଳାଇବାକୁ ମାସ/ବର୍ଷ ପରିବର୍ତ୍ତନ କରନ୍ତୁ।",
  "e.g. June 2026 regular payroll run": "ଉଦା. ଜୁନ୍ 2026 ନିୟମିତ ପେରୋଲ୍ ରନ୍",
  "Failed to create payroll cycle. It may already exist for this period.": "ପେରୋଲ୍ ଚକ୍ର ତିଆରି ହେଲା ନାହିଁ। ଏହି ଅବଧି ପାଇଁ ଏହା ପୂର୍ବରୁ ଥାଇପାରେ।",
  "Payroll Month *": "ପେରୋଲ୍ ମାସ *",
  "Payroll Period Setup": "ପେରୋଲ୍ ଅବଧି ସେଟଅପ୍",
  "Payroll settings not configured — dates default to month boundaries. Go to Settings → Payroll Configuration to set custom days.": "ପେରୋଲ୍ ସେଟିଂସ୍ ସେଟ୍ ହୋଇନାହିଁ — ତାରିଖ ମାସର ସୀମା ଅନୁସାରେ ଡିଫଲ୍ଟ ହୁଏ। ନିଜସ୍ୱ ଦିନ ସେଟ୍ କରିବାକୁ ସେଟିଂସ୍ → ପେରୋଲ୍ କନଫିଗରେସନ୍ କୁ ଯାଆନ୍ତୁ।",
  "Payroll Year *": "ପେରୋଲ୍ ବର୍ଷ *",
  "Please select a Company Code for this payroll run.": "ଦୟାକରି ଏହି ପେରୋଲ୍ ରନ୍ ପାଇଁ ଏକ କମ୍ପାନୀ କୋଡ୍ ବାଛନ୍ତୁ।",
  "Run Notes (optional)": "ରନ୍ ଟିପ୍ପଣୀ (ବୈକଳ୍ପିକ)",
  "Select a Company Code…": "ଏକ କମ୍ପାନୀ କୋଡ୍ ବାଛନ୍ତୁ…",
  "Step 1 of Wizard": "ୱିଜାର୍ଡର ପଦକ୍ଷେପ 1",
  "Your assigned Company Code": "ଆପଣଙ୍କୁ ଦିଆଯାଇଥିବା କମ୍ପାନୀ କୋଡ୍",
  "All Periods": "ସମସ୍ତ ଅବଧି",
  "ECR (Electronic Challan-cum-Return)": "ECR (ଇଲେକ୍ଟ୍ରୋନିକ୍ ଚାଲାନ୍-କମ୍-ରିଟର୍ଣ୍ଣ)",
  "ECR export is available after a payroll cycle is completed and payslips are dispatched. Complete a payroll run first.": "ପେରୋଲ୍ ଚକ୍ର ସମ୍ପୂର୍ଣ୍ଣ ହୋଇ ଦରମା ସ୍ଲିପ୍ ପଠାଯିବା ପରେ ECR ଏକ୍ସପୋର୍ଟ ଉପଲବ୍ଧ। ପ୍ରଥମେ ଏକ ପେରୋଲ୍ ରନ୍ ସମ୍ପୂର୍ଣ୍ଣ କରନ୍ତୁ।",
  "ECR is only available once payslips have been generated for this period.": "ଏହି ଅବଧି ପାଇଁ ଦରମା ସ୍ଲିପ୍ ପ୍ରସ୍ତୁତ ହେଲେ ହିଁ ECR ଉପଲବ୍ଧ।",
  "Excel": "Excel",
  "Export ECR file for EPFO submission": "EPFO ଦାଖଲ ପାଇଁ ECR ଫାଇଲ୍ ଏକ୍ସପୋର୍ଟ କରନ୍ତୁ",
  "Export Excel": "Excel ଏକ୍ସପୋର୍ଟ କରନ୍ତୁ",
  "Export PDF": "PDF ଏକ୍ସପୋର୍ଟ କରନ୍ତୁ",
  "Export Text (EPFO Upload)": "ଟେକ୍ସଟ୍ ଏକ୍ସପୋର୍ଟ କରନ୍ତୁ (EPFO ଅପଲୋଡ୍)",
  "Failed to download ECR {format}. Please try again.": "ECR {format} ଡାଉନଲୋଡ୍ ହେଲା ନାହିଁ। ଦୟାକରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "No payroll cycles yet. Run your first payroll to enable ECR export.": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ପେରୋଲ୍ ଚକ୍ର ନାହିଁ। ECR ଏକ୍ସପୋର୍ଟ ସକ୍ରିୟ କରିବାକୁ ଆପଣଙ୍କ ପ୍ରଥମ ପେରୋଲ୍ ଚଲାନ୍ତୁ।",
  "PDF": "PDF",
  "Select a period to export.": "ଏକ୍ସପୋର୍ଟ ପାଇଁ ଏକ ଅବଧି ବାଛନ୍ତୁ।",
  "text file": "ଟେକ୍ସଟ୍ ଫାଇଲ୍",
  "{count} employees · Net:": "{count} କର୍ମଚାରୀ · ନିଟ୍:",
  "All payslips dispatched. Employees have the configured window to raise queries.": "ସମସ୍ତ ଦରମା ସ୍ଲିପ୍ ପଠାଗଲା। ପ୍ରଶ୍ନ ଉଠାଇବା ପାଇଁ କର୍ମଚାରୀଙ୍କୁ ନିର୍ଦ୍ଧାରିତ ସମୟ ଅଛି।",
  "All payslips dispatched. Employees have until {date} to raise queries.": "ସମସ୍ତ ଦରମା ସ୍ଲିପ୍ ପଠାଗଲା। ପ୍ରଶ୍ନ ଉଠାଇବା ପାଇଁ କର୍ମଚାରୀଙ୍କୁ {date} ପର୍ଯ୍ୟନ୍ତ ସମୟ ଅଛି।",
  "Continue to Mark as Paid": "ପ୍ରଦତ୍ତ ଚିହ୍ନିତ କରିବାକୁ ଜାରି ରଖନ୍ତୁ",
  "Dispatch All": "ସମସ୍ତ ପଠାନ୍ତୁ",
  "Dispatch Payslips": "ଦରମା ସ୍ଲିପ୍ ପଠାନ୍ତୁ",
  "Dispatch payslips?": "ଦରମା ସ୍ଲିପ୍ ପଠାଇବେ?",
  "Dispatched": "ପଠାଗଲା",
  "Dispatching…": "ପଠାଯାଉଛି…",
  "Failed to dispatch payslips.": "ଦରମା ସ୍ଲିପ୍ ପଠାଯାଇପାରିଲା ନାହିଁ।",
  "No payslips found for this cycle.": "ଏହି ଚକ୍ର ପାଇଁ କୌଣସି ଦରମା ସ୍ଲିପ୍ ମିଳିଲା ନାହିଁ।",
  "This will email payslips to all {count} employee in this cycle (total net pay {amount}). Employees will be able to view and query them immediately. This cannot be undone.": "ଏହା ଏହି ଚକ୍ରର ସମସ୍ତ {count} କର୍ମଚାରୀଙ୍କୁ ଦରମା ସ୍ଲିପ୍ ଇମେଲ୍ କରିବ (ମୋଟ ନିଟ୍ ଦରମା {amount})। କର୍ମଚାରୀମାନେ ତୁରନ୍ତ ସେଗୁଡ଼ିକ ଦେଖି ପ୍ରଶ୍ନ କରିପାରିବେ। ଏହାକୁ ପୂର୍ବବତ୍ କରାଯାଇପାରିବ ନାହିଁ।",
  "This will email payslips to all {count} employees in this cycle (total net pay {amount}). Employees will be able to view and query them immediately. This cannot be undone.": "ଏହା ଏହି ଚକ୍ରର ସମସ୍ତ {count} କର୍ମଚାରୀଙ୍କୁ ଦରମା ସ୍ଲିପ୍ ଇମେଲ୍ କରିବ (ମୋଟ ନିଟ୍ ଦରମା {amount})। କର୍ମଚାରୀମାନେ ତୁରନ୍ତ ସେଗୁଡ଼ିକ ଦେଖି ପ୍ରଶ୍ନ କରିପାରିବେ। ଏହାକୁ ପୂର୍ବବତ୍ କରାଯାଇପାରିବ ନାହିଁ।",
  "Total ({count} employees)": "ମୋଟ ({count} କର୍ମଚାରୀ)",
  "Action Required — {count} Pending Cycle": "କାର୍ଯ୍ୟ ଆବଶ୍ୟକ — {count} ବାକି ଚକ୍ର",
  "Action Required — {count} Pending Cycles": "କାର୍ଯ୍ୟ ଆବଶ୍ୟକ — {count} ବାକି ଚକ୍ର",
