  "Payroll ready needs: {requirements}. Blocked: {noRecord} without a current salary record, {noStructure} without a salary structure, {noBank} without bank details.": "ପେରୋଲ୍ ପ୍ରସ୍ତୁତି ପାଇଁ ଦରକାର: {requirements}। ଅଟକିଛି: ବର୍ତ୍ତମାନର ଦରମା ରେକର୍ଡ ବିନା {noRecord}, ଦରମା ଗଠନ ବିନା {noStructure}, ବ୍ୟାଙ୍କ ବିବରଣୀ ବିନା {noBank}।",
