  "{count} employee(s) earning above ₹21,000 have no deductions. Ensure statutory config is set for their branch.": "₹21,000 ରୁ ଅଧିକ ଆୟ କରୁଥିବା {count} କର୍ମଚାରୀଙ୍କର କୌଣସି କଟୌତି ନାହିଁ। ସେମାନଙ୍କ ଶାଖା ପାଇଁ ଆଇନଗତ କନଫିଗରେସନ୍ ସେଟ୍ ହୋଇଛି ବୋଲି ନିଶ୍ଚିତ କରନ୍ତୁ।",
  "{count} employee(s) have more than 15 LOP days. Verify this is correct before proceeding.": "{count} କର୍ମଚାରୀଙ୍କର 15 ରୁ ଅଧିକ LOP ଦିନ ଅଛି। ଆଗକୁ ବଢ଼ିବା ପୂର୍ବରୁ ଏହା ଠିକ୍ ବୋଲି ଯାଞ୍ଚ କରନ୍ତୁ।",
  "{count} employee(s) have negative net pay. Deductions exceed gross earnings — review LOP or advance recovery entries.": "{count} କର୍ମଚାରୀଙ୍କର ନିଟ୍ ଦରମା ନକାରାତ୍ମକ। କଟୌତି ମୋଟ ଆୟଠାରୁ ଅଧିକ — LOP କିମ୍ବା ଅଗ୍ରିମ ଆଦାୟ ଏଣ୍ଟ୍ରି ସମୀକ୍ଷା କରନ୍ତୁ।",
  "{count} employee(s) have zero gross earnings. Check that their CTC and salary structure are configured correctly.": "{count} କର୍ମଚାରୀଙ୍କର ମୋଟ ଆୟ ଶୂନ୍ୟ। ସେମାନଙ୍କ CTC ଓ ଦରମା ଗଠନ ଠିକ୍ ଭାବେ ସେଟ୍ ହୋଇଛି କି ନାହିଁ ଯାଞ୍ଚ କରନ୍ତୁ।",
