  "All validation checks passed or acknowledged. Ready to generate payslips.": "ସମସ୍ତ ବୈଧତା ଯାଞ୍ଚ ପାସ୍ କିମ୍ବା ସ୍ୱୀକୃତ। ଦରମା ସ୍ଲିପ୍ ପ୍ରସ୍ତୁତ କରିବାକୁ ପ୍ରସ୍ତୁତ।",
