  "No issues detected. All {count} payslips look correct.": "କୌଣସି ସମସ୍ୟା ମିଳିଲା ନାହିଁ। ସମସ୍ତ {count} ଦରମା ସ୍ଲିପ୍ ଠିକ୍ ଦେଖାଯାଉଛି।",
  "No Payslips Generated": "କୌଣସି ଦରମା ସ୍ଲିପ୍ ପ୍ରସ୍ତୁତ ହୋଇନାହିଁ",
  "No payslips were generated. Click Back → Back → Earn & Deduct → \"Compute Salaries\" to reprocess after ensuring all employees have CTC configured.": "କୌଣସି ଦରମା ସ୍ଲିପ୍ ପ୍ରସ୍ତୁତ ହୋଇନାହିଁ। ସମସ୍ତ କର୍ମଚାରୀଙ୍କ CTC ସେଟ୍ ହୋଇଛି ବୋଲି ନିଶ୍ଚିତ କରି ପୁନଃ ପ୍ରକ୍ରିୟା ପାଇଁ ପଛକୁ → ପଛକୁ → ଆୟ ଓ କଟୌତି → \"ଦରମା ଗଣନା କରନ୍ତୁ\" କ୍ଲିକ୍ କରନ୍ତୁ।",
