  "The report is attached as a CSV file, built from what you are allowed to see. Each person receives their own copy.": "ରିପୋର୍ଟ ଏକ CSV ଫାଇଲ୍ ଭାବେ ସଂଲଗ୍ନ ହୁଏ, ଯାହା ଆପଣ ଦେଖିବାକୁ ଅନୁମତିପ୍ରାପ୍ତ ତଥ୍ୟରୁ ତିଆରି। ପ୍ରତ୍ୟେକ ବ୍ୟକ୍ତି ନିଜର ପ୍ରତିଲିପି ପାଆନ୍ତି।",
