  "Pro-rata Salary": "ଅନୁପାତିକ ଦରମା",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "ଅନୁପାତିକ ଦରମା, ଛୁଟି ନଗଦୀକରଣ ଓ ନୋଟିସ୍ ଅବଧି ଘାଟି ଆପେ ଆପେ ଗଣନା ହୁଏ (CTC ÷ 30, ଅର୍ଜିତ ଛୁଟି ବାକି) — ଏହା ସମୀକ୍ଷା ପାଇଁ ଏକ ପ୍ରାରମ୍ଭିକ ଆକଳନ, ଅନ୍ତିମ ଅଙ୍କ ନୁହେଁ। ଗ୍ରାଚୁଇଟି, ବୋନସ୍, ପ୍ରତିପୂରଣ, ଅଗ୍ରିମ ଓ TDS ସବୁବେଳେ ହାତରେ ଦିଆଯାଏ।",
  "Settlement finalized.": "ନିଷ୍ପତ୍ତି ଅନ୍ତିମ ହେଲା।",
  "Settlement updated.": "ନିଷ୍ପତ୍ତି ଅପଡେଟ୍ ହେଲା।",
  "This is a recovery — the employee owes the company (net payable may be negative)": "ଏହା ଏକ ଆଦାୟ — କର୍ମଚାରୀ କମ୍ପାନୀକୁ ଦେବେ (ନିଟ୍ ଦେୟ ନକାରାତ୍ମକ ହୋଇପାରେ)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ଏହା ପୂର୍ଣ୍ଣ ଓ ଅନ୍ତିମ ନିଷ୍ପତ୍ତିକୁ {amount} ନିଟ୍ ଦେୟରେ ଲକ୍ କରେ। ଥରେ ଅନ୍ତିମ ହେଲେ, ଏହି ନିଷ୍ପତ୍ତିର କୌଣସି ଫିଲ୍ଡ — ଗ୍ରାଚୁଇଟି, ବୋନସ୍, ପ୍ରତିପୂରଣ, ଅଗ୍ରିମ, TDS କିମ୍ବା ସଂଶୋଧନ — ପୁଣି ଏଡିଟ୍ କରାଯାଇପାରିବ ନାହିଁ। ଏହାକୁ ପୂର୍ବବତ୍ କରାଯାଇପାରିବ ନାହିଁ।",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ଏହା ପୂର୍ଣ୍ଣ ଓ ଅନ୍ତିମ ନିଷ୍ପତ୍ତିକୁ କର୍ମଚାରୀଙ୍କଠାରୁ {amount} ନିଟ୍ ଆଦାୟଯୋଗ୍ୟରେ ଲକ୍ କରେ। ଥରେ ଅନ୍ତିମ ହେଲେ, ଏହି ନିଷ୍ପତ୍ତିର କୌଣସି ଫିଲ୍ଡ — ଗ୍ରାଚୁଇଟି, ବୋନସ୍, ପ୍ରତିପୂରଣ, ଅଗ୍ରିମ, TDS କିମ୍ବା ସଂଶୋଧନ — ପୁଣି ଏଡିଟ୍ କରାଯାଇପାରିବ ନାହିଁ। ଏହାକୁ ପୂର୍ବବତ୍ କରାଯାଇପାରିବ ନାହିଁ।",
