  "extra access for just one specific employee, on top of their position.": "ପଦବୀ ଉପରେ, କେବଳ ଜଣେ ନିର୍ଦ୍ଦିଷ୍ଟ କର୍ମଚାରୀଙ୍କ ପାଇଁ ଅତିରିକ୍ତ ଆକ୍ସେସ୍।",
