  "Shown under \"Happy Birthday, [Name]!\" on every employee's dashboard, company-wide, whenever it's someone's birthday.": "କାହାର ଜନ୍ମଦିନ ହେଲେ, ପ୍ରତ୍ୟେକ କର୍ମଚାରୀଙ୍କ ଡ୍ୟାଶବୋର୍ଡରେ, ସମଗ୍ର କମ୍ପାନୀରେ \"ଜନ୍ମଦିନର ଶୁଭେଚ୍ଛା, [Name]!\" ତଳେ ଦେଖାଯାଏ।",
