  "Every ID is 8 digits and purely numeric. Each worker type has its own range, so the first digit tells you the type. The ID is picked automatically at hire; changing someone's type later does not change their existing ID.": "ପ୍ରତ୍ୟେକ ID 8 ଅଙ୍କର ଓ କେବଳ ସଂଖ୍ୟାତ୍ମକ। ପ୍ରତ୍ୟେକ କର୍ମୀ ପ୍ରକାରର ନିଜସ୍ୱ ପରିସର ଅଛି, ତେଣୁ ପ୍ରଥମ ଅଙ୍କ ପ୍ରକାର ଜଣାଏ। ନିଯୁକ୍ତି ସମୟରେ ID ସ୍ୱୟଂଚାଳିତ ଭାବେ ବଛାଯାଏ; ପରେ କାହାର ପ୍ରକାର ବଦଳାଇଲେ ତାଙ୍କ ବିଦ୍ୟମାନ ID ବଦଳେ ନାହିଁ।",
