  "Component Name": "ଅଂଶର ନାମ",
  "Computed automatically from each employee's branch (50% of Basic if the branch is marked Metro, 40% otherwise) — the Percentage field below is ignored for this calculation type.": "ପ୍ରତ୍ୟେକ କର୍ମଚାରୀଙ୍କ ଶାଖା ଅନୁସାରେ ସ୍ୱୟଂଚାଳିତ ଭାବେ ଗଣନା ହୁଏ (ଶାଖା ମେଟ୍ରୋ ଭାବେ ଚିହ୍ନିତ ଥିଲେ ମୂଳ ଦରମାର 50%, ନହେଲେ 40%) — ଏହି ଗଣନା ପ୍ରକାର ପାଇଁ ତଳେ ଥିବା ଶତକଡ଼ା ଫିଲ୍ଡ ଅଣଦେଖା ହୁଏ।",
