  "Captured on device": "ଡିଭାଇସ୍ ରେ ନିଆଯାଇଛି",
  "Capturing…": "ନିଆଯାଉଛି…",
  "Couldn't capture your location. Please allow location access and try again.": "ଆପଣଙ୍କ ସ୍ଥାନ ନିଆଯାଇପାରିଲା ନାହିଁ। ଦୟାକରି ସ୍ଥାନ ଆକ୍ସେସ୍ ଅନୁମତି ଦିଅନ୍ତୁ ଓ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
