  "Location saved for next time.": "ପରବର୍ତ୍ତୀ ଥର ପାଇଁ ସ୍ଥାନ ସଞ୍ଚିତ ହେଲା।",
  "Looked up from address": "ଠିକଣାରୁ ଖୋଜାଯାଇଛି",
  "Pick a saved location, capture a new one, or search an address — this is what your clock-in on approved WFH days gets checked against.": "ଏକ ସଞ୍ଚିତ ସ୍ଥାନ ବାଛନ୍ତୁ, ନୂଆ ଗୋଟିଏ ନିଅନ୍ତୁ, କିମ୍ବା ଠିକଣା ଖୋଜନ୍ତୁ — ଅନୁମୋଦିତ WFH ଦିନରେ ଆପଣଙ୍କ କ୍ଲକ୍-ଇନ୍ ଏହା ସହ ଯାଞ୍ଚ ହୁଏ।",
  "Reason is required.": "କାରଣ ଆବଶ୍ୟକ।",
  "Remove saved location \"{label}\"?": "ସଞ୍ଚିତ ସ୍ଥାନ \"{label}\" ହଟାଇବେ?",
  "Request Another": "ଆଉ ଏକ ଅନୁରୋଧ କରନ୍ତୁ",
