  "Save as… e.g. Home": "ଏହି ନାମରେ ସଞ୍ଚୟ କରନ୍ତୁ… ଉଦା. ଘର",
  "Saved Locations": "ସଞ୍ଚିତ ସ୍ଥାନ",
  "Search address": "ଠିକଣା ଖୋଜନ୍ତୁ",
  "Select a saved location or capture a new one to see its details here.": "ଏଠାରେ ବିବରଣୀ ଦେଖିବାକୁ ଏକ ସଞ୍ଚିତ ସ୍ଥାନ ବାଛନ୍ତୁ କିମ୍ବା ନୂଆ ଗୋଟିଏ ନିଅନ୍ତୁ।",
  "Select a saved location, capture your current one, or search an address before submitting — this is what your clock-in will be checked against on WFH days.": "ଦାଖଲ କରିବା ପୂର୍ବରୁ ଏକ ସଞ୍ଚିତ ସ୍ଥାନ ବାଛନ୍ତୁ, ଆପଣଙ୍କ ବର୍ତ୍ତମାନର ସ୍ଥାନ ନିଅନ୍ତୁ, କିମ୍ବା ଠିକଣା ଖୋଜନ୍ତୁ — WFH ଦିନରେ ଆପଣଙ୍କ କ୍ଲକ୍-ଇନ୍ ଏହା ସହ ଯାଞ୍ଚ ହେବ।",
  "Source": "ଉତ୍ସ",
  "Start Date": "ଆରମ୍ଭ ତାରିଖ",
  "tab. Open one to see its status or cancel it while it is still pending.": "ଟ୍ୟାବ୍ ରେ ତାଲିକାଭୁକ୍ତ। ଏହାର ସ୍ଥିତି ଦେଖିବାକୁ କିମ୍ବା ବାକି ଥିବା ବେଳେ ବାତିଲ୍ କରିବାକୁ ଗୋଟିଏ ଖୋଲନ୍ତୁ।",
  "View My Requests": "ମୋ ଅନୁରୋଧ ଦେଖନ୍ତୁ",
  "Why do you need to work from home? Your approver will read this.": "ଆପଣଙ୍କୁ ଘରୁ କାମ କାହିଁକି ଦରକାର? ଆପଣଙ୍କ ଅନୁମୋଦନକାରୀ ଏହା ପଢ଼ିବେ।",
  "Your browser doesn't support location capture.": "ଆପଣଙ୍କ ବ୍ରାଉଜର୍ ସ୍ଥାନ ନେବାକୁ ସମର୍ଥନ କରେ ନାହିଁ।",
  "Your existing requests are listed under": "ଆପଣଙ୍କ ବିଦ୍ୟମାନ ଅନୁରୋଧ ଏହା ଅଧୀନରେ ତାଲିକାଭୁକ୍ତ",
  "Your Location": "ଆପଣଙ୍କ ସ୍ଥାନ",
  "Your work-from-home request has been sent for approval.": "ଆପଣଙ୍କ ଘରୁ କାମ ଅନୁରୋଧ ଅନୁମୋଦନ ପାଇଁ ପଠାଯାଇଛି।",
  "Address matches": "ଠିକଣା ମେଳ ଖାଉଛି",
  "House / street, area, city, pincode": "ଘର / ରାସ୍ତା, ଅଞ୍ଚଳ, ସହର, ପିନକୋଡ୍",
  "No match found. Try adding the area, city or pincode.": "କୌଣସି ମେଳ ମିଳିଲା ନାହିଁ। ଅଞ୍ଚଳ, ସହର କିମ୍ବା ପିନକୋଡ୍ ଯୋଗ କରି ଦେଖନ୍ତୁ।",
  "The address search failed. Please try again.": "ଠିକଣା ଖୋଜା ବିଫଳ ହେଲା। ଦୟାକରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "Type at least the street, area and city.": "ଅନ୍ତତଃ ରାସ୍ତା, ଅଞ୍ଚଳ ଓ ସହର ଲେଖନ୍ତୁ।",
  "An approved request can't be cancelled from here. If your plans changed, ask your manager or HR.": "ଅନୁମୋଦିତ ଅନୁରୋଧ ଏଠାରୁ ବାତିଲ୍ କରାଯାଇପାରିବ ନାହିଁ। ଆପଣଙ୍କ ଯୋଜନା ବଦଳିଲେ, ଆପଣଙ୍କ ମ୍ୟାନେଜର କିମ୍ବା HR ଙ୍କୁ କୁହନ୍ତୁ।",
  "Cancel this work-from-home request?": "ଏହି ଘରୁ କାମ ଅନୁରୋଧ ବାତିଲ୍ କରିବେ?",
  "Work from home request": "ଘରୁ କାମ ଅନୁରୋଧ",
  "Work from home request cancelled.": "ଘରୁ କାମ ଅନୁରୋଧ ବାତିଲ୍ ହେଲା।",
  "You can punch from any location on these days (allowed by {name}).": "ଏହି ଦିନମାନଙ୍କରେ ଆପଣ ଯେକୌଣସି ସ୍ଥାନରୁ ପଞ୍ଚ୍ କରିପାରିବେ ({name} ଅନୁମତି ଦେଇଛନ୍ତି)।",
  "You can punch from any location on these days.": "ଏହି ଦିନମାନଙ୍କରେ ଆପଣ ଯେକୌଣସି ସ୍ଥାନରୁ ପଞ୍ଚ୍ କରିପାରିବେ।",
  "You must punch near this location. If you have moved, ask your manager or HR to allow punching from any location.": "ଆପଣଙ୍କୁ ଏହି ସ୍ଥାନ ନିକଟରେ ପଞ୍ଚ୍ କରିବାକୁ ହେବ। ଯଦି ଆପଣ ଅନ୍ୟତ୍ର ଯାଇଛନ୍ତି, ଯେକୌଣସି ସ୍ଥାନରୁ ପଞ୍ଚ୍ କରିବାକୁ ଅନୁମତି ଦେବାକୁ ଆପଣଙ୍କ ମ୍ୟାନେଜର କିମ୍ବା HR ଙ୍କୁ କୁହନ୍ତୁ।",
  "e.g. AIRA-LT-1042": "ଉଦା. AIRA-LT-1042",
