  "Optional at hiring time — assets are usually issued on the actual joining date.": "ନିଯୁକ୍ତି ସମୟରେ ବୈକଳ୍ପିକ — ସମ୍ପତ୍ତି ସାଧାରଣତଃ ପ୍ରକୃତ ଯୋଗଦାନ ତାରିଖରେ ଦିଆଯାଏ।",
