  "Failed to save basic details.": "ମୂଳ ବିବରଣୀ ସଞ୍ଚୟ ହେଲା ନାହିଁ।",
  "none": "କିଛି ନାହିଁ",
  "Pick an org unit first": "ପ୍ରଥମେ ଏକ ସଂଗଠନ ୟୁନିଟ୍ ବାଛନ୍ତୁ",
  "No fields are configured for this step.": "ଏହି ପର୍ଯ୍ୟାୟ ପାଇଁ କୌଣସି ଫିଲ୍ଡ ସେଟ୍ ହୋଇନାହିଁ।",
  "Add each qualification you've completed — at least one is required before you can submit.": "ଆପଣ ସମ୍ପୂର୍ଣ୍ଣ କରିଥିବା ପ୍ରତ୍ୟେକ ଯୋଗ୍ୟତା ଯୋଗ କରନ୍ତୁ — ଦାଖଲ କରିବା ପୂର୍ବରୁ ଅନ୍ତତଃ ଗୋଟିଏ ଆବଶ୍ୟକ।",
