  "Education Level": "ଶିକ୍ଷା ସ୍ତର",
  "Name it": "ଏହାର ନାମ ଦିଅନ୍ତୁ",
  "No education added yet — click below to add your first one.": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ଶିକ୍ଷା ଯୋଗ ହୋଇନାହିଁ — ପ୍ରଥମଟି ଯୋଗ କରିବାକୁ ତଳେ କ୍ଲିକ୍ କରନ୍ତୁ।",
  "Percentage / Grade": "ଶତକଡ଼ା / ଗ୍ରେଡ୍",
  "Specify Specialization": "ବିଶେଷଜ୍ଞତା ଉଲ୍ଲେଖ କରନ୍ତୁ",
  "Add Previous Employer": "ପୂର୍ବ ନିଯୁକ୍ତିଦାତା ଯୋଗ କରନ୍ତୁ",
  "Employment Type": "ନିଯୁକ୍ତି ପ୍ରକାର",
  "experience letter": "ଅଭିଜ୍ଞତା ପତ୍ର",
  "I currently work here": "ମୁଁ ବର୍ତ୍ତମାନ ଏଠାରେ କାମ କରୁଛି",
  "Key Responsibilities": "ମୁଖ୍ୟ ଦାୟିତ୍ୱ",
  "No previous employers added yet — optional, but add any you have.": "ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ପୂର୍ବ ନିଯୁକ୍ତିଦାତା ଯୋଗ ହୋଇନାହିଁ — ବୈକଳ୍ପିକ, କିନ୍ତୁ ଥିଲେ ଯୋଗ କରନ୍ତୁ।",
  "Reason for Leaving": "ଛାଡ଼ିବାର କାରଣ",
  "Work Experience": "କାର୍ଯ୍ୟ ଅଭିଜ୍ଞତା",
  "{age} yr": "{age} ବର୍ଷ",
  "{age} yrs": "{age} ବର୍ଷ",
  "Close {name}": "{name} ବନ୍ଦ କରନ୍ତୁ",
  "Dependent on the employee": "କର୍ମଚାରୀଙ୍କ ଉପରେ ନିର୍ଭରଶୀଳ",
  "Family member: {name}": "ପରିବାର ସଦସ୍ୟ: {name}",
  "new": "ନୂଆ",
  "New family member": "ନୂଆ ପରିବାର ସଦସ୍ୟ",
  "this family member": "ଏହି ପରିବାର ସଦସ୍ୟ",
  "{count} dependant": "{count} ନିର୍ଭରଶୀଳ",
  "{count} dependants": "{count} ନିର୍ଭରଶୀଳ",
  "{count} family member": "{count} ପରିବାର ସଦସ୍ୟ",
  "{count} family members": "{count} ପରିବାର ସଦସ୍ୟ",
  "A nominee is picked from the family list, and there is nobody in it yet. Add a family member with a name above, then add the nominee.": "ନାମାଙ୍କିତ ବ୍ୟକ୍ତି ପରିବାର ତାଲିକାରୁ ବଛାଯାଏ, ଏବଂ ଏଥିରେ ଏପର୍ଯ୍ୟନ୍ତ କେହି ନାହାଁନ୍ତି। ଉପରେ ନାମ ସହିତ ଏକ ପରିବାର ସଦସ୍ୟ ଯୋଗ କରନ୍ତୁ, ତା'ପରେ ନାମାଙ୍କିତ ବ୍ୟକ୍ତି ଯୋଗ କରନ୍ତୁ।",
  "Add a family member with a name above before adding a nominee.": "ନାମାଙ୍କିତ ବ୍ୟକ୍ତି ଯୋଗ କରିବା ପୂର୍ବରୁ ଉପରେ ନାମ ସହିତ ଏକ ପରିବାର ସଦସ୍ୟ ଯୋଗ କରନ୍ତୁ।",
  "Add the people who depend on the employee or who may be nominated below. A person is added once and can be picked as a nominee.": "କର୍ମଚାରୀଙ୍କ ଉପରେ ନିର୍ଭରଶୀଳ କିମ୍ବା ନାମାଙ୍କିତ ହୋଇପାରିବା ବ୍ୟକ୍ତିମାନଙ୍କୁ ତଳେ ଯୋଗ କରନ୍ତୁ। ଜଣେ ବ୍ୟକ୍ତି ଥରେ ଯୋଗ ହୁଅନ୍ତି ଏବଂ ନାମାଙ୍କିତ ବ୍ୟକ୍ତି ଭାବେ ବଛାଯାଇପାରିବେ।",
  "Another {relationship} is already listed.": "ଆଉ ଜଣେ {relationship} ପୂର୍ବରୁ ତାଲିକାଭୁକ୍ତ ଅଛନ୍ତି।",
  "Each scheme's shares should add up to 100% across its nominees. Pick nominees from the family list above.": "ପ୍ରତ୍ୟେକ ଯୋଜନାର ଅଂଶ ଏହାର ନାମାଙ୍କିତ ବ୍ୟକ୍ତିଙ୍କ ମଧ୍ୟରେ ମୋଟ 100% ହେବା ଉଚିତ। ଉପରେ ପରିବାର ତାଲିକାରୁ ନାମାଙ୍କିତ ବ୍ୟକ୍ତି ବାଛନ୍ତୁ।",
  "EPF / Gratuity nomination": "EPF / ଗ୍ରାଚୁଇଟି ମନୋନୟନ",
