  "Review everything below before submitting. Use": "ଦାଖଲ କରିବା ପୂର୍ବରୁ ତଳେ ସବୁକିଛି ସମୀକ୍ଷା କରନ୍ତୁ। ବ୍ୟବହାର କରନ୍ତୁ",
