  "Drag and drop a file onto any row below, or click Upload. Accepted: PDF, JPG, PNG · Max 5 MB each.": "ତଳେ ଯେକୌଣସି ଧାଡ଼ିରେ ଏକ ଫାଇଲ୍ ଟାଣି ଛାଡ଼ନ୍ତୁ, କିମ୍ବା ଅପଲୋଡ୍ କ୍ଲିକ୍ କରନ୍ତୁ। ଗ୍ରହଣୀୟ: PDF, JPG, PNG · ପ୍ରତ୍ୟେକ ସର୍ବାଧିକ 5 MB।",
