  "You won't be able to submit your onboarding profile until this step is complete.": "ଏହି ପର୍ଯ୍ୟାୟ ସମ୍ପୂର୍ଣ୍ଣ ନହେବା ପର୍ଯ୍ୟନ୍ତ ଆପଣ ଆପଣଙ୍କ ଅନବୋର୍ଡିଂ ପ୍ରୋଫାଇଲ୍ ଦାଖଲ କରିପାରିବେ ନାହିଁ।",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, and it takes effect immediately.": "ୱେବ୍ କ୍ଲକ୍-ଇନ୍/ଆଉଟ୍ ପାଇଁ ଆପଣଙ୍କ ସଂଗଠନ ଏକ ପଞ୍ଜୀକୃତ Face ID ଆବଶ୍ୟକ କରେ। ଏଠାରେ ଥରେ ପଞ୍ଜୀକରଣ କରନ୍ତୁ — ଏହା ପ୍ରକୃତରେ ଆପଣ ବୋଲି ନିଶ୍ଚିତ କରିବାକୁ ଆମେ ଏକ ଶୀଘ୍ର ଲାଇଭନେସ୍ ଯାଞ୍ଚ କରୁ, ଏବଂ ଏହା ତୁରନ୍ତ କାର୍ଯ୍ୟକାରୀ ହୁଏ।",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, then send it to HR for approval.": "ୱେବ୍ କ୍ଲକ୍-ଇନ୍/ଆଉଟ୍ ପାଇଁ ଆପଣଙ୍କ ସଂଗଠନ ଏକ ପଞ୍ଜୀକୃତ Face ID ଆବଶ୍ୟକ କରେ। ଏଠାରେ ଥରେ ପଞ୍ଜୀକରଣ କରନ୍ତୁ — ଏହା ପ୍ରକୃତରେ ଆପଣ ବୋଲି ନିଶ୍ଚିତ କରିବାକୁ ଆମେ ଏକ ଶୀଘ୍ର ଲାଇଭନେସ୍ ଯାଞ୍ଚ କରୁ, ତା'ପରେ ଅନୁମୋଦନ ପାଇଁ HR ଙ୍କୁ ପଠାଉ।",
