  "{count} employee has no joining date. They are left out of attendance and payroll until HR corrects it.": "{count} କର୍ମଚାରୀଙ୍କର ଯୋଗଦାନ ତାରିଖ ନାହିଁ। HR ସଂଶୋଧନ ନକରିବା ପର୍ଯ୍ୟନ୍ତ ସେମାନେ ଉପସ୍ଥିତି ଓ ପେରୋଲ୍ ରୁ ବାଦ୍ ଅଛନ୍ତି।",
  "{count} employees have no joining date. They are left out of attendance and payroll until HR corrects it.": "{count} କର୍ମଚାରୀଙ୍କର ଯୋଗଦାନ ତାରିଖ ନାହିଁ। HR ସଂଶୋଧନ ନକରିବା ପର୍ଯ୍ୟନ୍ତ ସେମାନେ ଉପସ୍ଥିତି ଓ ପେରୋଲ୍ ରୁ ବାଦ୍ ଅଛନ୍ତି।",
