  "Head turn ✓ — now blink naturally": "ମୁଣ୍ଡ ଘୁରାଇବା ✓ — ଏବେ ସ୍ୱାଭାବିକ ଭାବେ ଆଖି ପିଛୁଳାନ୍ତୁ",
