  "Slowly turn your head slightly to one side, then back": "ଧୀରେ ଧୀରେ ମୁଣ୍ଡକୁ ଟିକିଏ ଗୋଟିଏ ପାଖକୁ ଘୁରାନ୍ତୁ, ତା'ପରେ ଫେରାନ୍ତୁ",
