  "Register your Face ID": "ଆପଣଙ୍କ Face ID ପଞ୍ଜୀକରଣ କରନ୍ତୁ",
  "Couldn't confirm you're live": "ଆପଣ ଜୀବନ୍ତ ବୋଲି ନିଶ୍ଚିତ କରାଯାଇପାରିଲା ନାହିଁ",
  "Face registration needs your camera. Allow camera access for this site in your browser's settings, then try again.": "ମୁହଁ ପଞ୍ଜୀକରଣ ପାଇଁ ଆପଣଙ୍କ କ୍ୟାମେରା ଆବଶ୍ୟକ। ଆପଣଙ୍କ ବ୍ରାଉଜରର ସେଟିଂସ୍ ରେ ଏହି ସାଇଟ୍ ପାଇଁ କ୍ୟାମେରା ଆକ୍ସେସ୍ ଦିଅନ୍ତୁ, ତା'ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "Register your face": "ଆପଣଙ୍କ ମୁହଁ ପଞ୍ଜୀକରଣ କରନ୍ତୁ",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure you're well-lit and centered, then try again.": "ପଞ୍ଜୀକରଣ ପାଇଁ ସ୍ୱାଭାବିକ ଆଖି ପିଛୁଳା ଓ ମୁଣ୍ଡକୁ ଟିକିଏ ଘୁରାଇବା ଉଭୟ ଆବଶ୍ୟକ, ଏବଂ ଆମେ ଉଭୟକୁ ସମୟରେ ଦେଖିପାରିଲୁ ନାହିଁ। ଭଲ ଆଲୋକରେ ଓ ମଝିରେ ରହିବାକୁ ନିଶ୍ଚିତ କରନ୍ତୁ, ତା'ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "Registration submitted!": "ପଞ୍ଜୀକରଣ ଦାଖଲ ହେଲା!",
  "Sending your registration for approval…": "ଆପଣଙ୍କ ପଞ୍ଜୀକରଣ ଅନୁମୋଦନ ପାଇଁ ପଠାଯାଉଛି…",
  "Submitting": "ଦାଖଲ ହେଉଛି",
  "Update your face ID": "ଆପଣଙ୍କ Face ID ଅପଡେଟ୍ କରନ୍ତୁ",
  "We couldn't get a reliably clear capture — this becomes your permanent face ID reference, so it's worth getting right. Try better lighting and hold steady.": "ଆମେ ଏକ ନିର୍ଭରଯୋଗ୍ୟ ସ୍ପଷ୍ଟ କ୍ୟାପ୍ଚର୍ ପାଇପାରିଲୁ ନାହିଁ — ଏହା ଆପଣଙ୍କ ସ୍ଥାୟୀ Face ID ରେଫରେନ୍ସ ହୁଏ, ତେଣୁ ଠିକ୍ ହେବା ଜରୁରୀ। ଭଲ ଆଲୋକ ବ୍ୟବହାର କରନ୍ତୁ ଏବଂ ସ୍ଥିର ରୁହନ୍ତୁ।",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "ଆମେ କ୍ୟାମେରା ଆକ୍ସେସ୍ ମାଗିବୁ, ଏହା ଆପଣ ହିଁ ବୋଲି ନିଶ୍ଚିତ କରିବାକୁ ଏକ ଶୀଘ୍ର ଜୀବନ୍ତତା ଯାଞ୍ଚ (ଆଖି ପିଛୁଳା ଓ ମୁଣ୍ଡକୁ ଟିକିଏ ଘୁରାଇବା) କରିବୁ, ତା'ପରେ ଆପଣଙ୍କ Face ID HR ଅନୁମୋଦନ ପାଇଁ ପଠାଇବୁ। କୌଣସି ଫଟୋ କିମ୍ବା ଭିଡିଓ କେବେ ପଠାଯାଏ ନାହିଁ — କେବଳ ଏକ ସାଂଖ୍ୟିକ ମୁହଁ ସଙ୍କେତ।",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your updated face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "ଆମେ କ୍ୟାମେରା ଆକ୍ସେସ୍ ମାଗିବୁ, ଏହା ଆପଣ ହିଁ ବୋଲି ନିଶ୍ଚିତ କରିବାକୁ ଏକ ଶୀଘ୍ର ଜୀବନ୍ତତା ଯାଞ୍ଚ (ଆଖି ପିଛୁଳା ଓ ମୁଣ୍ଡକୁ ଟିକିଏ ଘୁରାଇବା) କରିବୁ, ତା'ପରେ ଆପଣଙ୍କ ଅପଡେଟ୍ ହୋଇଥିବା Face ID HR ଅନୁମୋଦନ ପାଇଁ ପଠାଇବୁ। କୌଣସି ଫଟୋ କିମ୍ବା ଭିଡିଓ କେବେ ପଠାଯାଏ ନାହିଁ — କେବଳ ଏକ ସାଂଖ୍ୟିକ ମୁହଁ ସଙ୍କେତ।",
  "Your face registration request has been sent to HR for approval. You'll be notified once it's reviewed.": "ଆପଣଙ୍କ ମୁହଁ ପଞ୍ଜୀକରଣ ଅନୁରୋଧ ଅନୁମୋଦନ ପାଇଁ HR ଙ୍କ ପାଖକୁ ପଠାଯାଇଛି। ସମୀକ୍ଷା ହେଲେ ଆପଣଙ୍କୁ ଜଣାଯିବ।",
  "Low light detected — your screen is now acting as a light. Raising your screen brightness helps.": "କମ୍ ଆଲୋକ ଜଣାପଡ଼ିଲା — ଆପଣଙ୍କ ସ୍କ୍ରିନ୍ ଏବେ ଆଲୋକ ଭଳି କାମ କରୁଛି। ସ୍କ୍ରିନ୍ ଉଜ୍ଜ୍ୱଳତା ବଢ଼ାଇଲେ ସାହାଯ୍ୟ ମିଳିବ।",
  "Please allow camera access in the browser prompt to punch in or out.": "ପଞ୍ଚ୍ ଇନ୍ କିମ୍ବା ଆଉଟ୍ କରିବାକୁ ବ୍ରାଉଜର୍ ପ୍ରମ୍ପ୍ଟରେ କ୍ୟାମେରା ଆକ୍ସେସ୍ ଦିଅନ୍ତୁ।",
  "Preparing face verification": "ମୁହଁ ଯାଞ୍ଚ ପ୍ରସ୍ତୁତ ହେଉଛି",
  "Verify Your Identity": "ଆପଣଙ୍କ ପରିଚୟ ଯାଞ୍ଚ କରନ୍ତୁ",
  "We couldn't get a reliably clear capture to verify against your registered face. Try better lighting and hold steady.": "ଆପଣଙ୍କ ପଞ୍ଜୀକୃତ ମୁହଁ ସହ ମିଳାଇବା ପାଇଁ ଆମେ ଏକ ନିର୍ଭରଯୋଗ୍ୟ ସ୍ପଷ୍ଟ କ୍ୟାପ୍ଚର୍ ପାଇପାରିଲୁ ନାହିଁ। ଭଲ ଆଲୋକ ବ୍ୟବହାର କରନ୍ତୁ ଏବଂ ସ୍ଥିର ରୁହନ୍ତୁ।",
  "We didn't detect a slight head turn in time. Make sure you're well-lit and centered, then try again.": "ଆମେ ସମୟରେ ମୁଣ୍ଡର ଟିକିଏ ଘୁରାଇବା ଜାଣିପାରିଲୁ ନାହିଁ। ଭଲ ଆଲୋକରେ ଓ ମଝିରେ ରହିବାକୁ ନିଶ୍ଚିତ କରନ୍ତୁ, ତା'ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
  "Your account requires face verification to punch in or out. Allow camera access for this site in your browser's settings, then try again.": "ପଞ୍ଚ୍ ଇନ୍ କିମ୍ବା ଆଉଟ୍ କରିବାକୁ ଆପଣଙ୍କ ଖାତା ପାଇଁ ମୁହଁ ଯାଞ୍ଚ ଆବଶ୍ୟକ। ଆପଣଙ୍କ ବ୍ରାଉଜରର ସେଟିଂସ୍ ରେ ଏହି ସାଇଟ୍ ପାଇଁ କ୍ୟାମେରା ଆକ୍ସେସ୍ ଦିଅନ୍ତୁ, ତା'ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
