  "in the {count} module shown?": "ଦେଖାଯାଇଥିବା {count} ମଡ୍ୟୁଲ୍ ରେ?",
  "in the {count} modules shown?": "ଦେଖାଯାଇଥିବା {count} ମଡ୍ୟୁଲ୍ ରେ?",
  "No module matches. Clear the search or choose “All modules”.": "କୌଣସି ମଡ୍ୟୁଲ୍ ମେଳ ଖାଉନାହିଁ। ସନ୍ଧାନ ସଫା କରନ୍ତୁ କିମ୍ବା “ସମସ୍ତ ମଡ୍ୟୁଲ୍” ବାଛନ୍ତୁ।",
