  "Switch every {action} permission on or off for the modules shown": "ଦେଖାଯାଇଥିବା ମଡ୍ୟୁଲ୍ ପାଇଁ ପ୍ରତ୍ୟେକ {action} ଅନୁମତି ଚାଲୁ କିମ୍ବା ବନ୍ଦ କରନ୍ତୁ",
  "Switch ON {count} more permission": "ଆଉ {count} ଅନୁମତି ଚାଲୁ କରନ୍ତୁ",
  "Switch ON {count} more permissions": "ଆଉ {count} ଅନୁମତି ଚାଲୁ କରନ୍ତୁ",
  "The checkbox at the top of a column switches that action for every module shown": "ସ୍ତମ୍ଭର ଉପରେ ଥିବା ଚେକ୍ବକ୍ସ ଦେଖାଯାଇଥିବା ପ୍ରତ୍ୟେକ ମଡ୍ୟୁଲ୍ ପାଇଁ ସେହି କାର୍ଯ୍ୟ ବଦଳାଏ",
  "This includes delete, export and approve rights.": "ଏଥିରେ ଲିଭାଇବା, ଏକ୍ସପୋର୍ଟ ଓ ଅନୁମୋଦନ ଅଧିକାର ଅନ୍ତର୍ଭୁକ୍ତ।",
