  "Comfortable rows": "ଆରାମଦାୟକ ଧାଡ଼ି",
  "Compact rows: more modules on screen": "ସଂକୁଚିତ ଧାଡ଼ି: ସ୍କ୍ରିନ୍ ରେ ଅଧିକ ମଡ୍ୟୁଲ୍",
