  "Allow camera access for this site in your browser's settings, then try again — or upload a photo from your device instead.": "ଆପଣଙ୍କ ବ୍ରାଉଜରର ସେଟିଂସ୍ ରେ ଏହି ସାଇଟ୍ ପାଇଁ କ୍ୟାମେରା ଆକ୍ସେସ୍ ଦିଅନ୍ତୁ, ତା'ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ — କିମ୍ବା ତା' ବଦଳରେ ଆପଣଙ୍କ ଡିଭାଇସ୍ ରୁ ଫଟୋ ଅପଲୋଡ୍ କରନ୍ତୁ।",
