  "Allow office punches without Face ID until a Face ID is approved": "Face ID ଅନୁମୋଦିତ ନହେବା ପର୍ଯ୍ୟନ୍ତ Face ID ବିନା କାର୍ଯ୍ୟାଳୟ ପଞ୍ଚ୍ ଅନୁମତି ଦିଅନ୍ତୁ",
