  "Employee registers (active immediately)": "କର୍ମଚାରୀ ପଞ୍ଜୀକରଣ କରନ୍ତି (ତୁରନ୍ତ ସକ୍ରିୟ)",
  "Employee registers, HR approves": "କର୍ମଚାରୀ ପଞ୍ଜୀକରଣ କରନ୍ତି, HR ଅନୁମୋଦନ କରନ୍ତି",
